local _, ns = ...

if (type(GetLocale) ~= "function") or GetLocale() ~= "enUS" then return end
local _, ns = ...

ns.DungeonGuide = {
    ruins_of_lordaeron = {
        tagline = "Undead ruins beneath the ruined city of Lordaeron: six bosses, a non-linear layout, and one of the first dungeons most players meet.",
        tips = {
            "Non-linear dungeon: the six bosses can be tackled in any order, and skipping one does not block progress.",
            "Viktor the Vile is a hidden boss — light the fire in the chimney of the building southwest of Lordamere Overlook and clear five add waves before he appears; he sometimes fails to spawn on the beta.",
            "The Spirit Healer stands right outside the entrance, so the corpse run after a wipe is very short.",
            "The quests still show as red at level 17, but the dungeon itself is clearable at that level.",
            "Mob density is high and it is easy to pull several packs in a row; without crowd control, low levels will struggle.",
        },
        entrance = {
            H = "The entrance sits in the non-instanced Ruins of Lordaeron directly above the Undercity (Tirisfal Glades, south of Brill).",
            A = {
                "Players with the Stormwind Mage Tower portal to Dalaran unlocked can teleport straight there and skip most of the sea voyage;",
                "Take the boat from Stormwind Harbor to Auberdine;",
                "Switch boats on the other side of the Auberdine dock to Menethil Harbor;",
                "Stay on this boat until it takes you to Southshore in Hillsbrad Foothills;",
                "follow the road from Southshore to Hillsbrad Fields, then head north around Dalaran;",
                "swim north across Lordamere Lake in Silverpine Forest into Tirisfal Glades;",
                "follow the road to the Ruins of Lordaeron entrance.",
            },
        },
        trash = {
            { title = "Spider wing",
              text = "The spiders near the entrance come in packs and patrol. A single pack is easy; the trouble is pulling a patrolling pack along with it — keep an eye out and pull packs back toward you." },
            { title = "Skeletal Soldiers and Banshees",
              text = "Skeletal Soldiers patrol near the Baron and the Banshees can silence; in groups they hit hard. Stun-type crowd control makes these packs much easier." },
            { title = "Flesh Golems",
              text = "They hit hard and have a knock-away that also reduces threat. Watch your positioning when you pull them so you are not knocked into another pack — the Lordamere Overlook they patrol is dense with trash." },
            { title = "Ghouls",
              text = "Packs of 3–4 with heavy melee swings, packed right next to other groups, so it is very easy to chain-pull. Do not get greedy — too many at once will overwhelm the tank and healer." },
        },
        bosses = {
            { en = "Witherfang",
              text = "Patrols King's Alley — a simple tank-and-spank. He brings two spiders, so kill those first, stun whenever you can, and dispel Leech Poison off the tank." },
            { en = "The Baron",
              text = "Hits hard and has only one ability, Knockout: heavy instant damage plus a threat drop. He can kill the tank outright if the tank is not at full health — stun him out of the cast whenever possible." },
            { en = "Viktor the Vile",
              text = "Hidden boss located in the chimney of the building southwest of Lordamere Overlook — light the fire and clear five add waves before he appears. He has only heavy melee and Leech Poison, so let the tank build aggro first. He sometimes fails to spawn on the beta." },
            { en = "The Abandoned",
              text = "Found as soon as you enter Market Street from Lordamere Overlook. The statues in the area trigger three add waves first. He casts Frost Nova, applies a chill to anyone who lands melee hits on him, and casts Drain Life on the tank — interrupt or stun him before the cast finishes." },
            { en = "Bjork",
              text = "Has only a very short Anti-Magic Shell, and once it drops he is a plain tank-and-spank — the easiest boss here." },
            { en = "Rath'mael",
              text = "Has only Flamestrike: start moving as soon as he begins the cast — it always lands where the tank stood when the cast started; a stun can stop him from casting it at all." },
        },
    },
    hall_of_thanes = {
        tagline = "A dwarven hall deep inside Old Ironforge beneath Ironforge: four bosses in a linear layout, and one of the early dungeons for Alliance players.",
        tips = {
            "The dungeon sits right inside Old Ironforge behind Ironforge's throne room — no walk to speak of, and the Spirit Healer is at the entrance too, so corpse runs are very short.",
            "Dark Iron Engineer bombs lock their landing spot as soon as the throw starts — sidestep when you see the wind-up and the damage is 100% avoidable.",
            "Lesser Stone Golems hit extremely hard and move faster — pull one at a time whenever possible; when you pull several, kill them one by one instead of splitting damage.",
            "The vaults in the final room, the Reliquary of Kings, hold enough quest items for all 5 party members to complete their quests.",
            "Except for An Ancient Grudge and Important Heirlooms, all dungeon quests are Alliance-exclusive.",
        },
        entrance = {
            H = "The Horde route is long: from Undercity through Silverpine Forest, Hillsbrad Foothills and Arathi Highlands into the Wetlands, then south through the tunnel into Dun Morogh and on to Ironforge; the dungeon entrance is in Old Ironforge behind the throne room.",
            A = {
                "Take the tram from Stormwind to Ironforge;",
                "Cross Ironforge's great hall to the throne room;",
                "The dungeon entrance is in Old Ironforge behind the throne room.",
            },
        },
        trash = {
            { title = "Dark Iron Looter and Dark Iron Engineer",
              text = "The intro mobs are not too serious, and the trash only gets challenging once you reach the Dark Iron side: Looters deal rapid dagger auto-attacks, and pulling too many at once drains the tank's health fast; Engineers throw bombs at a target location. Do not pull too many — especially at lower levels; the bomb location is locked as the throw starts and is fully avoidable. Focus down the Looters first — their damage is rapid and can be deadly." },
            { title = "Dark Iron Summoner and Fiery Assistant",
              text = "The Summoner is a caster-type mob that casts Fireballs and summons a Fiery Assistant. Use any pillar or wall to break line of sight, preventing the cast and forcing it to run toward the party." },
            { title = "Lesser Stone Golem",
              text = "They hit extremely hard and move faster. Pull one at a time if you can; when you pull several, focus them down one by one instead of spreading damage. The final pack is a Summoner, a Looter and a Stone Golem — we recommend crowd control (such as Polymorph) so only two are active at the start, killing the Stone Golem first and then the Looter; stuns like Kidney Shot help a lot too." },
        },
        bosses = {
            { en = "Faldrim Anvilmar",
              text = "Patrols the center of Anvilmar's Rest and is a simple tank-and-spank fight. The main concern is accidentally pulling the boss along with trash as he patrols: clear out a section of the room and wait for him to patrol to your side before pulling. He auto-attacks and casts Mind Blast, and applies a 10-minute Curse of Anvilmar to the tank." },
            { en = "Magmatus",
              text = "Accompanied by a Dark Iron Summoner, with a couple of abilities that really put a focus on healing. On pull the tank should drag the boss away from the party while the Summoner is focused — the boss periodically unleashes a Fire Nova-like area attack; once the Summoner is down, burn the boss. He also casts Combust on a random player." },
            { en = "Plunder",
              text = "Patrols his hallway with only one ability: a Knockback. Pull the boss in a safe area where nobody gets knocked into other mobs, and have everyone stand against a wall or in a corner to further mitigate the mechanic." },
            { en = "Durgen Dirgehammer",
              text = "The final encounter here, accompanied by two Lesser Stone Golems with Looters around the edge of the room. Clear all the Looters before starting — the boss has an AoE Fear and a Rend, which is heavy damage on the tank. Take the golems out one by one and use stuns and fears to mitigate damage." },
        },
    },
    ragefire_chasm = {
        tagline = "A lava cave beneath Orgrimmar: 4 bosses on a short linear route with trivial mechanics, widely considered the easiest dungeon in the game.",
        tips = {
            "The dungeon sits deep in the Cleft of Shadow inside Orgrimmar — the entrance is right there, and the Spirit Healer at the door makes for a short corpse run.",
            "All 5 dungeon quests are Horde-exclusive — pick them all up before entering.",
            "Several bosses come with 1-2 adds: CC one before the pull, nuke the remaining add down, then switch to the boss.",
            "Taragaman the Hungerer stands on a lava-ringed platform: have the tank pull him away from the edge, keep ranged at max distance so Fire Nova deals minimal damage and Uppercut cannot knock anyone off.",
            "Tuned for levels 13-18 with low mob density and simple mechanics — groups without CC can clear it comfortably.",
        },
        entrance = {
            H = "The entrance is at the far end of the Cleft of Shadow inside Orgrimmar — walk in and zone in; no travel required.",
            A = {
                "Take the boat to Ratchet;",
                "run north along the Barrens to its northeastern tip and sneak into Orgrimmar through the less-populated west entrance;",
                "strip off your armor and corpse-run your way to the Cleft of Shadow until you can safely zone into the instance.",
            },
        },
        bosses = {
            { en = "Oggleflint",
              text = "Oggleflint is flanked by 2 troggs in his room. Make sure to CC at least one trogg before engaging him. Allow your tank to pick up the remaining add and face Oggleflint away from the group (cleave). All dps should work to nuke down the add first as before switching to Oggleflint. Make sure to kill the CC'ed add once the boss and the first add are dead." },
            { en = "Taragaman the Hungerer",
              text = "Taragaman the Hungerer is stationed in the middle of a platform surrounded by lava. Have your tank pull him away from the edges of the platform so that Uppercut does not knock him off the platform. Make sure your range is at max range so Fire Nova inflicts minimal damage. The rest of the fight is a basic tank-and-spank." },
            { en = "Jergosh the Invoker",
              text = "Like Oggleflint, Jergosh the Invoker is flanked by two mobs. One of the mobs should be CC'ed while the other is focused down before transitioning to Jergosh. He casts Immolate and Curse of Weakness which can be a problem for tanks trying to gain threat and intense on healers, but overall this is a simple and straightforward fight." },
            { en = "Bazzalan",
              text = "Bazzalan also has 2 adds, but the mob on the right (his left) can be pulled without engaging the boss, greatly reducing the difficulty of the fight. The other mob should be CC'ed while the group focuses on the boss as he deals significant single-target damage and should be killed ASAP. Other than that, another tank-and-spank." },
        },
    },
    wailing_caverns = {
        tagline = "A serpent-filled cavern beneath the Lushwater Oasis in the Northern Barrens: 7 bosses across a confusing non-linear layout, with the Druids of the Fang's sleep spell as the biggest threat throughout.",
        tips = {
            "This is the game's first non-linear dungeon with many forks — new groups get lost easily, so study the map before entering.",
            "Every Druid of the Fang, boss or trash, casts Sleep Druid's Slumber — up to a 15-second incapacitate that can hit your tank or healer. Interrupt it immediately, every time.",
            "Two or more sleeping druids in one fight is nearly a guaranteed wipe: pull them one at a time and instantly CC any extra pulls.",
            "After slaying all 4 Lords of the Fang you can start the Naralex event: escort the Disciple of Naralex to the ritual stone. If the Disciple dies or the group wipes, the event fails and can only be retried after a full instance reset.",
            "Killing Verdan the Everliving unlocks the waterfall shortcut behind him.",
            "There are 7 quests in total (2 Horde-exclusive, 5 neutral) — pick them all up before entering.",
        },
        entrance = {
            H = "From the Crossroads, travel southwest to the Lushwater Oasis and find the cavern entrance; the instance portal lies at the end of the winding cavern.",
            A = {
                "Start from Astranaar in Ashenvale;",
                "head south into the Northern Barrens;",
                "reach the Lushwater Oasis southwest of the Crossroads and enter the cavern to zone in.",
            },
        },
        trash = {
            { title = "Druid of the Fang",
              text = "Druid of the Fang is the only trash mob that demands real attention: a hard-hitting caster whose Sleep Druid's Slumber can incapacitate any target for up to 15 seconds, effectively neutralizing your healer if it lands. Fight them one at a time and CC any extras; interrupt Sleep on sight. After a while they cast on themselves, silencing them and removing the sleep threat for good." },
        },
        bosses = {
            { en = "Lord Cobrahn",
              text = "Before the pull, Lord Cobrahn will be surrounded by 3 Deviate Python. They are between levels 18 and 19, and are non-elites, making them easy to AOE down. Prioritize these pythons before switching to Cobrahn. Like all of the Druids in the Wailing Caverns, Cobrahn may cast the dangerous Sleep ability, which should be interrupted immediately, especially if the target is your healer. At some point during the encounter, Cobrahn will transform into a serpent, increasing his damage by 50 and attack speed by 43%." },
            { en = "Lady Anacondra",
              text = "Lady Anacondra is likely to be the first of the Druid bosses you will encounter in the Wailing Caverns. Like all of the druids, she has four abilities, 2 of which are shared by her contemporaries (Lightning Bolt and Sleep). Her most threatening ability is 'Sleep,' which can be applied to anyone in your party, including the Tank or Healer. To deal with this ability, make sure to interrupt it immediately. If you happen to pull another Druid of the Fang during the encounter, make sure to CC it right away as one 'Sleep' can be dealt with, but 2 or more will result in a wipe. If your interrupts are on point and you've pulled carefully, this fight should be easy." },
            { en = "Kresh",
              text = "Kresh is a straightforward tank and spank, featuring only one ability that occasionally dazes its target. Kresh has a large amount of armor and base damage, and if you have a melee-heavy group, this fight can drag on and be a slight nuisance for your healer. Overall, this is not a challenging encounter." },
            { en = "Lord Pythas",
              text = "Lord Pythas, like his fellow Druid counterparts, is most dangerous due to his 'Sleep' ability. Additionally, he is flanked by one additional Druid of the Fang and a Deviate Shambler. Make sure to CC the Druid and interrupt Pythas whenever he casts Sleep. Prioritize the Shambler and burn it down before switching to Pythas, but make sure either your tank or one melee DPS stays focused on Pythas, so the Sleep is interrupted." },
            { en = "Skum",
              text = "Skum is a simple tank-and-spank boss with only one significant ability; Chained Bolt. This is a chain lightning-style spell that will strike three melee units if they are close together. Make sure your melee spread out around the boss to avoid the damage. Spreading out is not a hard requirement, as the ability itself deals minimal damage. Skum is entirely optional, but his loot makes him worthwhile." },
            { en = "Lord Serpentis",
              text = "Lord Serpentis is the last of the 4 Druids of the Fang. He shares abilities with his counterparts and is only dangerous due to his Sleep ability. As with the other Druids, interrupt Sleep, and the fight is a cakewalk. Unlike the other Druids, Serptenis can be pulled without any additional trash, making this encounter easier than the rest." },
            { en = "Verdan the Everliving",
              text = "Verdan the Everliving has one significant ability, which roots all targets within 10 yards for 10 seconds and knocks them down for 2 seconds. The ability does damage as well, so healers should keep their eye on the group's health pools. Ranged DPS should stand at max range to avoid the root. Aside from that, Verdan is a tank-and-spank and should always be killed to unlock the waterfall shortcut behind him." },
            { en = "Mutanus the Devourer",
              text = "The first part of the event is simple; escort the Disciple through the Wailing Caverns towards the ritual stone. To escort him, will require you to clear out any remaining adds on the way to the rock, most of which should already be cleared by progressing through the dungeon. Once the Disciple reaches Naralex and begins his final ritual, waves of adds will approach the Disciple to kill him. Burn down the adds while keeping your AOE DPS alive. After the 2nd wave of adds, Mutanus will appear to kill your group and the Disciple. He is very challenging, as he possesses two forms of crowd control that can be used against your group. Additionally, his Thundercrack ability does a massive amount of damage to nearby targets, making this fight a nightmare for your melee DPS. Mutanus is a group composition check - make sure to have a healthy set of ranged DPS and at least one hybrid healing class aside from your main healer to assist with the thunderclap damage. There are no special tricks for this fight - stay at max range while healing up the group and try to stay alive. This fight is worth the trouble, as the loot is quite good." },
            { en = "Deviate Faerie Dragon",
              text = "Deviate Faerie Dragon is a low armor, high damage mob that possesses no significant abilities. The challenge in this encounter comes from the fact that this is a 4-mob pull, all of which are elites. Two Druids of the Fang are also included in this pull, meaning that Druid's Slumber is likely to go off in this fight. Your strategy should be to CC one of the Druids while burning the other one down and interrupting its 'Sleep' whenever possible. Your tank will be taking damage from 3 different elites here, so if you have any hybrid classes in your group aside from the healer, make sure that they weave in some support heals during their rotation. This fight will test your group's ability to focus down a single target, so if you're coordinated and all on the same page, it should be a breeze." },
        },
    },
    the_deadmines = {
        tagline = "A pirate den deep in the Moonbrook mine of Westfall: 8 bosses (one rare) on a linear route — most Alliance players' first dungeon.",
        tips = {
            "Many pulls pack 5-6 mobs: bring crowd control (Polymorph, Freezing Trap, etc.) and mark a kill target on every pull.",
            "In the Goblin Foundry, engineers cast Summon Remote-Controlled Golem to summon a deadly robot: stun the cast, or kill the engineer first — the golem despawns with its summoner.",
            "The ship is patrolled heavily, and patrols love to catch groups while they loot, roll and drink after a boss kill — stay alert and pan your camera.",
            "Before Sneed's Shredder, clear every Miner in the room or the fear can pull your group into extra mobs.",
            "VanCleef summons 2 more adds at 50% health; the fight is heal-intensive throughout, so hybrids should spot-heal the tank.",
        },
        entrance = {
            H = "A long trip for Horde: take the zeppelin to Grom'gol Base Camp in Stranglethorn Vale, swim north along the shoreline to the southern tip of Westfall, then head to Moonbrook.",
            A = {
                "Fly to Sentinel Hill in Westfall;",
                "travel south into Moonbrook and find the mine entrance;",
                "fight your way through the mine to the instance portal — there are mobs along the way, so go as a group.",
            },
        },
        trash = {
            { title = "Goblin Engineer and Craftsman",
              text = "Goblin Craftsman and Goblin Engineer, found in the Goblin Foundry before Gilnid, are two of the most vicious mobs in the dungeon. Their Summon Remote-Controlled Golem summons a deadly miniature robot: stun them mid-cast (a Paladin's Hammer of Justice works perfectly) or CC the extras. If a golem does get summoned, kill the goblin first — the golem despawns once its summoner dies." },
            { title = "Defias Squallshaper",
              text = "Defias Squallshaper is a caster mob in the Dreadnaught room whose Frost Nova can be frustrating for tanks and melee: stack the group on the tank when pulling so nobody gets caught in a dead zone, and beware patrolling Squallshapers novaing you out of position." },
            { title = "Dungeon Patrols",
              text = "Patrols are everywhere and often catch groups off guard while they loot, roll and drink after a boss kill. No special trick required — just pan your camera around as you progress, especially after boss kills." },
        },
        bosses = {
            { en = "Rhahk'Zor",
              text = "Rhahk'Zor is flanked by 2 Defias Watchman in his room. Both of them can be pulled without pulling Rhahk'Zor himself. If you are unable to pull them cleanly, make sure to CC at least one archer once to limit the incoming damage your group will be taking. Also, beware of any patrolling elites that might aggro after the pull. Aside from that, this fight is a simple tank-and-spank as Rhahk'Zor is little more than a pseudo-boss and warmup for the dungeon." },
            { en = "Miner Johnson",
              text = "Miner Johnson is the epitome of a tank-and-spank. He has one single target ability that reduces the tanks armor, so aside from the fight requiring intensive tank healing, it is a straightforward encounter. The only problem is that he is surrounded by numerous Defias Miner. However, they are non-elites with small health pools. Try to pick as many of them off as possible before pulling Johnson. I recommend that if you happen to have a hybrid DPS class in your group, have the hybrid also heal the tank when the Pierce Armor debuff is up to guarantee the kill." },
            { en = "Sneed",
              text = "The Sneed's Shredder fight begins before pulling the boss. Due to the Shredder's Terrify ability, the entire room must be cleared of all Goblin Woodcarver. Otherwise, players might be feared into them and cause a wipe. Aside from clearing the room, the boss is a very straightforward tank-and-spank. Once the Shredder has been defeated, Sneed will hop out of the machine and continue the fight himself. He has a disarm ability that can be annoying for tanks trying to pick up aggro, so give the tank ample time to acquire threat before going ham on the boss. Overall, this is a simple boss encounter." },
            { en = "Sneed's Shredder",
              text = "The Sneed's Shredder fight begins before pulling the boss. Due to the Shredder's Terrify ability, the entire room must be cleared of all Goblin Woodcarver. Otherwise, players might be feared into them and cause a wipe. Aside from clearing the room, the boss is a very straightforward tank-and-spank. Once the Shredder has been defeated, Sneed will hop out of the machine and continue the fight himself. He has a disarm ability that can be annoying for tanks trying to pick up aggro, so give the tank ample time to acquire threat before going ham on the boss. Overall, this is a simple boss encounter." },
            { en = "Gilnid",
              text = "Gilnid like many of the bosses in this dungeon, is mostly a simple tank-and-spank. He is flanked by a Goblin Engineer that will pull once Gilnid has been engaged. Make sure to CC the engineer as he may cast Summon Remote-Controlled Golem, which summons a mechanical robot that is immune to most abilities. If the robot does get summoned, focus the engineer that summoned it as the robot will despawn once its summoner is dead. You can avoid this headache by simply CCing the add before the pull." },
            { en = "Mr. Smite",
              text = "Mr. Smite and two invisible Defias Blackguard engage automatically as you approach the plank leading up to him. Smite casts Smite Stomp at 66% and 33% health, stunning the group for 10 seconds, so the Blackguards need to be killed before the boss reaches 66%. During these stuns, the boss will run to a chest and pick up a weapon and adding new abilities. After 33%, make sure the tank is topped up to avoid sudden death during a Smite Slam. Aside from the adds and stuns, this is a straightforward encounter." },
            { en = "Captain Greenskin",
              text = "Be sure to CC one of the adds next to Captain Greenskin before the pull. I recommend that you CC the Defias Squallshaper as their frost nova ability can be quite annoying. Once you've engaged the boss, begin by killing the Defias Companion first as it is non-elite and will die quickly. After that, kill the remaining Defias Pirate and then swap to Greenskin while keeping your CC on the Squallshaper. Make sure to face Greenskin away from the group as his cleave can be quite nasty. When he dies, finish off the Squallshaper and loot his corpse." },
            { en = "Edwin VanCleef",
              text = "When you engage Edwin VanCleef, two Defias Blackguard will break stealth and attack you as well. Like Mr. Smite, make sure to deal with these mobs first. CC one and 'skull' mark the other and burn it down quickly, as Van Cleef does a tremendous amount of single-target damage and can shred your tank. Once both of the adds are dealt with, focus back on VC. Once he hits 50% health, he will summon 2 more adds for you to deal with. It remains quite heal-intensive so the healers and hybrids in your group should be on their toes and provide spot-healing as it is needed. The Defias Leather Cloak will drop the first time you kill VanCleef." },
            { en = "Cookie",
              text = "The most challenging part about Cookie is the leap off the ship to engage him. The bottom deck of the ship is packed with elites that can easily aggro if a jump is not timed correctly. Assuming you've timed the jump correctly, pull Cookie off the ship towards the exit of the dungeon. The fight is a simple tank-and-spank. Make sure to interrupt the Cookie's Cooking spell as it heals Cookie for a fair chunk. The rest is easy." },
        },
    },
    shadowfang_keep = {
        tagline = "A worgen-infested keep in Silverpine Forest: 8 bosses on a linear route — a Classic Horde leveling staple, though a long trip for the Alliance.",
        tips = {
            "Mobs here love Curses, Magic and Disease debuffs — bring a dispeller. Many mobs are skinnable too, a nice perk for skinners.",
            "Shadowfang Moonwalkers gain Anti-Magic Shield, 10 seconds of full magic immunity: bring at least one extra melee besides the tank to burn them through it faster.",
            "Wailing Guardsmen cast Screams of the Past, silencing everyone within 5 yards for 5 seconds: keep casters — especially your healer — at least 5 yards away.",
            "Baron Silverlaine's Veil of Shadow Veil of Shadow cuts healing received by 75%: hybrids should assist with tank healing or the tank drops fast.",
            "Archmage Arugal is by far the hardest boss: massive Void Bolts and random teleports. Have ranged DPS stand on the platform upon entering and burn him from there; melee should wait for the teleport instead of chasing.",
            "All 3 dungeon quests are Horde-exclusive.",
        },
        entrance = {
            H = "Fly to The Sepulcher in Silverpine Forest, travel south along the road, then west until you reach the Keep north of Pyrewood Village.",
            A = {
                "Fly to Southshore in the Hillsbrad Foothills;",
                "follow the main road west into Silverpine Forest;",
                "continue west and then a bit north to reach Shadowfang Keep, just north of Pyrewood Village.",
            },
        },
        trash = {
            { title = "Shadowfang Moonwalker",
              text = "Shadowfang Moonwalker, found mainly in the courtyard, gains Anti-Magic Shield — immunity to all magical spells for 10 seconds. Dealing with them is about group composition: bring at least one extra melee besides the tank (two is even better) to burn them down faster during the immunity window." },
            { title = "Wailing Guardsman",
              text = "Wailing Guardsman, a ghostly humanoid on the upper levels, casts Screams of the Past, silencing all players within 5 yards for 5 seconds. Keep spellcasters at least 5 yards away — especially your healer." },
        },
        bosses = {
            { en = "Rethilgore",
              text = "Rethilgore is a tank and spank in the truest sense of the word. His only ability, Soul Drain, is negligable. He also has a moderately low health pool and a Loot table comparable to his difficulty. The only thing you should be aware of are the mobs surrounding him, 2 of which should be pulled prior to engaging the boss. The one mob that will remain, a Bleak Worg, should be polymorphed or burned down first prior to switching DPS to Rethilgore." },
            { en = "Fel Steed / Shadow Charger",
              text = "The Fel Steed and Shadow Charger deal an incredibly high amount of damage and pulling one of them will pull all three, regardless of how carefully you pull the first mob. Make sure to polymorph at least one of the horses and have a hunter or warlock pet tank the second while your main tank and DPS is focused on the third before cycling to the next mob. Your healer should be aware of the massive amount of damage that will be incoming during this encounter." },
            { en = "Razorclaw the Butcher",
              text = "Razorclaw the Butcher is a simple tank and spank. Make sure to clear the room before you pull him, as well as the surrounding patrols. His Abilities are negligible, and no further explanation is required." },
            { en = "Baron Silverlaine",
              text = "What makes Baron Silverlaine challenging is his higher level (24) and his primary ability, Veil of Shadow. This ability reduces healing effects on a target by 75%, effectively serving as a beefed up mortal strike. Make sure your hybrid classes are assisting the healer here with tank healing as the tank will go down quickly otherwise. Aside from that, the fight is a tank and spank." },
            { en = "Commander Springvale",
              text = "Commander Springvale is flanked by two mobs that will pull with him. The first is a Haunted Servitor, which should be burned down quickly. The second is a Wailing Guardsman, which would pulled by either a hunter or warlock pet away from the group as it can cast an AOE silence that can potentially wipe the party. Make sure to prioritize Springvale after the Servitor is killed, and interrupt his healing spells. Once he's down, take out the guardsman who again should be tanked off to the side by either a pet or possibly a Warrior/Druid offtank." },
            { en = "Odo the Blindwatcher",
              text = "Odo the Blindwatcher is flanked by 2 Vile Bat which will pull with him once engaged. These bats have a disarm and a cleave ability, so they should be faced away from the group while being tanked. One of the bats may be polymorphed if you have a mage. Make sure to let the tank generate some threat before going ham on the boss as the disarm can be quite annoying to deal. Kill the bats first before switching over to Odo, and you should be fine." },
            { en = "Deathsworn Captain",
              text = "Deathsworn Captain is a rare elite that should be tanked away from the group as his cleave ability can do a severe amount of damage. If you will him with any wailing guardsmen, make sure to tank him at least 10 yards away from the guardsman to avoid the AOE silence. Aside from that, the fight is a tank and spank." },
            { en = "Fenrus the Devourer",
              text = "Fenrus the Devourer is an easy enough boss, with their only notable ability being a DoT. This encounter is a straightforward tank and spank." },
            { en = "Wolf Master Nandos",
              text = "Four Worgs circle Wolf Master Nandos in a barn-like room, make sure to kill all Worgs before engaging him. If you pull the Worgs alongside him, make sure to kill them first before transitioning back to Nandos. He will summon Worgs periodically throughout the fight. Make sure to kill them instantly before switching back to Nandos. This fight is all about prioritizing adds first so if you can do that you will be fine." },
            { en = "Archmage Arugal",
              text = "Arugal is by far the hardest boss in the dungeon. His Void Bolts hit for a massive amount of damage, and his teleport makes him difficult to lock down. To make this as easy as possible, have your ranged DPS stand on the platform as soon as you enter his room. They should be able to DPS Arugal down from that point no matter where he teleports. Have your melee DPS stand there as well and wait for Argual's teleport to their location, so they don't end up lining the healer while trying to chase him down." },
        },
    },
    blackfathom_deeps = {
        tagline = "A sunken temple off the Zoram Strand in Ashenvale: 6 bosses across a long, watery layout — keep an eye on your breath meter.",
        tips = {
            "The entrance is underwater — swim in through a submerged tunnel, and sections like Old Serra'kis' lair require diving. Breath meters run out much faster in Classic, so plan ahead.",
            "Per Patch 1.12 rules up to 10 players may enter together, though 5 remains the typical group size.",
            "Several large packs await: crowd control shines here, and many packs contain casters — stun, fear or interrupt them.",
            "Twilight Lord Kelris' sleep can catch your healer off guard: keep the tank topped off and have hybrids assist healing.",
            "After Kelris, light the four braziers around the Azshara statue to start the Fire of Aku'mai event: 4 waves total, the first turtle wave being the nastiest — an offtank, a pet or an Evasion-tank rogue needs to pick one up.",
            "There are 9 quests in total (4 Alliance, 4 Horde, 1 neutral) — pick them up before entering.",
        },
        entrance = {
            H = "Fly to Sun Rock Retreat in the Stonetalon Mountains, take the Talondeep Path into Ashenvale, then follow the main path northwest to the Zoram Strand to find the entrance.",
            A = {
                "Fly to Astranaar in Ashenvale;",
                "head northwest along the main path to the Zoram Strand;",
                "dive into the underwater passage at the shore to zone in.",
            },
        },
        bosses = {
            { en = "Ghamoo-ra",
              text = "Ghamoo-ra is a simple tank and spank with a catch - the boss has a tremendous amount of armor and takes significantly reduced damage. Every so often, he will cast his primary ability, so make sure to stay spread out. This is a simple encounter with very little explanation required." },
            { en = "Lady Sarevess",
              text = "Lady Sarevess patrols the area with 2 other Naga. Make sure to clear out the cave before pulling her and her 2 bodyguards. Make sure to CC at least one of the bodyguards before engaging her. Focus the add down and switch to Sarevess." },
            { en = "Gelihast",
              text = "Gelihast is a straightforward encounter with a small twist - his room is packed with Murlocs. While the fight with Geli requires no explanation, you must be very careful when pulling the adds around the room prior to pulling the boss. Gelihast has a nasty net ability which can leave your tank in an awkward position to subsequently pull additional mobs, so it is crucial that you clear his room first before you pull him. Once he's dead, click on the altar behind him for a small buff." },
            { en = "Twilight Lord Kelris",
              text = "Twilight Lord Kelris is not a particularly dangerous boss, although his sleep ability may catch your healer off guard. Make sure to keep the tank topped off in the event the healer is slept, and have all hybrid classes heal the tank if such an event happens." },
            { en = "Old Serra'kis",
              text = "Old Serra'kis is an optional loot pinata with no real abilities. The only thing you should be mindful of is your breath meter while under water. Remember, in Classic WoW, the breath meter lasts far less time." },
            { en = "Aku'mai",
              text = "Aku'mai is a tank and spank with massive single target damage due to his frenzy ability. Make sure to stay away from his poison cloud so the healer can focus heals on the tank. Hybrid classes should offer healing assistance here if possible, and the tank should use a health pot if he has one. Overall, this is a very simple fight." },
        },
    },
    the_stockade = {
        tagline = "The prison beneath Stormwind's Mage Quarter: 5 bosses plus a rare, a very short linear run packed with dense pulls — one of the fastest XP dungeons for the Alliance.",
        tips = {
            "The dungeon sits in the northeast corner of Stormwind's Mage Quarter with the Meeting Stone right outside — you're in the instance as soon as you're in the city.",
            "Almost every pack is melee humanoids: perfect for AoE farming, and easily crowd-controlled with Polymorph and friends.",
            "Defias Prisoners use Disarm (Disarm), which makes threat-building hard for the tank: against multiple prisoners, let the tank build threat before attacking and CC what you can.",
            "Dextren Ward's fear Intimidating Shout is brutal: clear every add in the surrounding corridors first so the fear cannot drag in extras.",
            "The rare Bruegal Ironknuckle drops the best loot in the dungeon — don't skip him if he's up.",
            "All 6 dungeon quests are Alliance-exclusive.",
        },
        entrance = {
            H = "Getting here as Horde is a nightmare most skip: zeppelin to Grom'gol Base Camp in Stranglethorn Vale, swim north along the shore to the southern tip of Westfall, head east through Elwynn Forest and up into Stormwind — stripping off all your gear and being ready for several rez-runs.",
            A = {
                "Head to the northeast corner of the Mage Quarter in Stormwind;",
                "the Meeting Stone is right outside the instance entrance — walk in and zone in.",
            },
        },
        trash = {
            { title = "Defias Prisoner",
              text = "Defias Prisoner is one of the most tedious mobs in the dungeon: its Disarm disarms and makes it hard for tanks to generate threat. Against multiple Prisoners, give the tank time to build threat before attacking, and CC if you can." },
        },
        bosses = {
            { en = "Kam Deepfury",
              text = "Like Targorr and many of the other bosses in this dungeon, Kam Deepfury is surrounded by a few Defias in his room. Make sure to CC at least one Defias before engaging him. Allow your tank to pick up the remaining add and Kam and station him away from the CC'ed add. All DPS should work to nuke down the add first as before switching to Kam. Make sure to kill the CC'ed add once the boss and the first add are dead." },
            { en = "Targorr the Dread",
              text = "A few Defias surround Targorr the Dread in his room. Make sure to CC at least one Defias before engaging him. Allow your tank to pick up the remaining add and Targorr and station him away from the CC'ed add. All DPS should work to nuke down the add first as before switching to Targorr. Make sure to kill the CC'ed add once the boss and the first add are dead." },
            { en = "Hamhock",
              text = "Two Defias flank Hamhock. Make sure to CC at least one Defias before engaging him. Allow your tank to pick up the remaining add and Hamhock and station him away from the CC'ed add. All DPS should work to nuke down the add first as before switching to Hamhock. Be wary of his Chain Lightning ability, which can be nasty in melee heavy groups. Make sure to spread out as much as possible to reduce its damage." },
            { en = "Bazil Thredd",
              text = "Bazil Thredd is a simple tank and spank in theory, but his high level and Smoke Bomb make him difficult for some groups. Make sure to keep the tank topped off, so he/she does not die during a smoke bomb stun. Bazil deals a high amount of single target damage, so if you have any hybrid DPS in your group, make sure to have them support the healer and spot-heal the tank when needed." },
            { en = "Dextren Ward",
              text = "Dextren Ward is one of the most challenging bosses in this dungeon due to his Intimidating Shout. Make sure to clear all of the adds in the surrounding corridors, so no one in your group mistakenly pulls additional adds during the fear duration. If you pull extra Defias mobs with Dextren, make sure to CC them as best you can and focus down Dextren first, as his fear can be tremendously punishing. If you have done a good job with clearing the adds and the rooms around him, this fight should be no problem at all." },
            { en = "Bruegal Ironknuckle",
              text = "Bruegal Ironknuckle is simple, straightforward, and drops the best loot the dungeon has to offer. However, because he is a rare spawn, you are unlikely to find him during your run. Make sure to clear the adds around him before engaging. He is the literal definition of a tank and spank." },
        },
    },
    gnomeregan = {
        tagline = "The gnomes' former capital beneath Dun Morogh: 5 bosses plus a rare across a sprawling, maze-like layout — one of Classic's most confusing dungeons to navigate.",
        tips = {
            "The dungeon has two entrances in the Train Depot: the front entrance (west side) leads to the Clockwerk Run, the backdoor entrance (north side) leads to the Engineering Labs — the backdoor requires the Workman's Key or engineering skill of at least 150.",
            "Horde have a teleport shortcut: pick up the Chief Engineer Scooty quest from at the shop in Orgrimmar (available at level 20), take the boat from Ratchet to Booty Bay, find on the lower docks floor near the inn, and get beamed straight into the dungeon with the Goblin Transponder.",
            "Many pulls mix elites with large packs of non-elites: AoE and cleave are extremely valuable. Expect Troggs, Diseased Gnomes and Mechs.",
            "During the Mekgineer Thermaplugg fight, six bomb dispensers keep spawning Walking Bombs: either kill the bombs before they reach the group, or assign a player to shut each dispenser down with the button on its right-hand side.",
            "Electrocutioner 6000 drops the Workman's Key — groups needing the backdoor should make sure someone loots it.",
            "There are 12 quests in total (7 Alliance, 2 Horde, 3 neutral).",
        },
        entrance = {
            H = "Horde can teleport in: pick up the Chief Engineer Scooty quest from at the shop in Orgrimmar (level 20+), take the boat from Ratchet to Booty Bay, find on the lower floor of the docks near the inn, complete the quest and get beamed straight into the dungeon with the Goblin Transponder.",
            A = {
                "From Ironforge, travel west along the road through Dun Morogh to Gnomeregan;",
                "the dungeon has two entrances in the Train Depot: the front entrance (west side) leads to the Clockwerk Run, and the backdoor entrance (north side) leads to the Engineering Labs.",
            },
        },
        bosses = {
            { en = "Grubbis",
              text = "Grubbis is located near the instance entrance in the cave area connected to the Hall of Gears. To start the event to spawn Grubbis, speak to Blastmaster Emi Shortfuse. Once the event has started, mobs will spawn from the cave before Emi triggers explosives to close it off. Grubbis will spawn from the second cave before the explosives go off." },
            { en = "Viscous Fallout",
              text = "Viscous Fallout is located in the Hall of Gears on the irradiated ground level. It is recommended to clear out the trash mobs around them so they can be pulled without any adds." },
            { en = "Electrocutioner 6000",
              text = "Electrocutioner 6000 is located in the Launch Bay on the elevated launch pad, suspended above the circular walkway at the center of the room." },
            { en = "Crowd Pummeler 9-60",
              text = "Crowd Pummeler 9-60 is located in the Engineering Labs and can be found on the upper southern ledge." },
            { en = "Dark Iron Ambassador",
              text = "Dark Iron Ambassador is located near the end of the instance leading up to the Tinkers' Court. Given their rare nature, they may not always spawn. If they do spawn, they tend to patrol on the north side of the tunnel leading to Mekgineer Thermaplugg." },
            { en = "Mekgineer Thermaplugg",
              text = "Mekgineer Thermaplugg is located at the end of the instance in the Tinkers' Court. During the encounter, Walking Bombs will spawn from the six bomb dispensers. Groups can either kill the bombs before they reach the group, or designate a player to shut down the bomb dispensers by pressing the button on the right-hand side of each dispenser." },
        },
    },
    razorfen_kraul = {
        tagline = "Razorfen Kraul is a linear quillboar-den dungeon where trash control and interrupts matter as much as the bosses — a classic step-up dungeon around level 30.",
        tips = {
            "Bring plenty of crowd control (Polymorph, Freezing Trap, Banish and so on) — most packs here revolve around CC-then-kill.",
            "Prioritize the Earthgrab Totems and caster mobs; roots and stuns chained on the wrong target can wipe the group.",
            "Death Speaker Jargba's mind control and Overlord Ramtusk's burst damage are the two main wipe points — clear and CC before engaging.",
            "Don't skip the Blind Hunter rare in the Bat Cave — great loot, and Hunters can tame it as a pet.",
            "Tank the caster bosses (like Charlga Razorflank) away from packs and patrols; timely interrupts significantly ease the healing load.",
        },
        entrance = {
            H = "Horde players can simply travel to the southern part of the Barrens and head west before reaching the Great Lift to find the entrance.",
            A = {
                "Take the boat from Menethil Harbor to Theramore Isle.",
                "Run to the southern part of Dustwallow Marsh and head west before you reach the Great Lift to find the entrance.",
            },
        },
        trash = {
            { title = "Razorfen Totemic",
              text = "is one of the most annoying mobs in RFK. Their chief ability, Earthgrab Totem, summons an Earthgrab Totem that lasts 30 sec. and periodically immobilizes nearby enemies. If rooted out of position, your group may be at risk of pulling additional mob packs. Deal with this ability by prioritizing the Earthgrab Totem before killing any other mob in a pack." },
            { title = "Razorfen Dustweaver",
              text = "is similar to the Totemic, only instead of a rooting totem, it can cast which is a cyclone-like ability that stuns a target for 10 seconds. If this is cast on the healer, the tank should be wary of pulling too many mobs. The best way to deal with the dustweavers is to pull only 1 at a time and have the hybrid classes prepared to toss a heal onto the tank if necessary." },
            { title = "Death's Head Adept",
              text = "also casts a CC ability, . Like the totemic, make sure to only pull one of these at a time and have your group positioned away from any additional mobs or patrols. Because they are casters, the Death's Head Adepts are easy to kill, but can be dangerous if they catch you off guard." },
        },
        bosses = {
            { en = "Roogug",
              text = "Roogug is optional and tied to the Shaman- and Warrior-exclusive class quests. Roogug is a simple encounter with one notable exception: the surrounding mobs. Before engaging Roogug, make sure to clear the area and CC whatever mobs you can prior to engagement. If you have a Warlock with Banish, make sure to use it on the elemental at his side to reduce incoming damage onto the tank." },
            { en = "Aggem Thorncurse",
              text = "Aggem Thorncurse is a simple tank and spank with the ability to summon a boar guardian to aide him in battle. When he summons the boar, prioritize it and kill it before switching back to Aggem." },
            { en = "Death Speaker Jargba",
              text = "Death Speaker Jargba pulls with two caster mobs, making this fight quite tough. With his Dominate Mind ability, Jargba can turn the tides of battle by MCing one of your party members. Additionally, the caster allies do massive amounts of damage. In order to survive this engagement, you must CC at least 1 of the mobs beside Jargba, ideally both. Take the boss out quickly to get rid of the MC threat, and then finish off the casters to ensure victory." },
            { en = "Overlord Ramtusk",
              text = "Overlord Ramtusk is a vivaciously strong boss with high single target damage. He is also flanked by 2 Razorfen Spearhide, whose Whirling Barrage ability makes them particularly lethal. In order to prevent your tank from getting decimated, make sure to CC both of the spearhides if you can. From there, focus down Ramtusk for an easy kill." },
            { en = "Agathelos the Raging",
              text = "Agathelos the Raging is a straightforward encounter, though this boss deals massive single-target damage. Most of this fight's difficulty is keeping the tank alive, which will fall on the healer and any hybrid DPS your group might have." },
            { en = "Blind Hunter",
              text = "Blind Hunter is a simple fight that takes place inside the Bat Cave in RFK. Make sure your casters stop casting when he begins casting his Sonic Burst (Sonic Boom), which is an AOE silence ability. Aside from that, the fight is a simple tank and spank with fantastic loot. This Rare can be tamed by Hunters and is a sought-after pet." },
            { en = "Earthcaller Halmgar",
              text = "If you have a Warlock with Banish, use it on the elemental and kill Earthcaller Halmgar. Otherwise, clear the platform, prioritize his totems, and burst the elemental down quickly before switching to Halmgar." },
            { en = "Charlga Razorflank",
              text = "Charlga Razorflank is a caster that deals quite a bit of damage but has low armor. Pull the boss down from her hut and tank her on the platform below. Make sure to interrupt her casts and have your group spread out to avoid extra damage. Every so often, Charlga will go immune to all abilities and also has a healing spell, extending the duration of the fight. Compared to Ramtusk and Jargba, this should be a piece of cake." },
        },
    },
    razorfen_downs = {
        tagline = "Razorfen Downs is a Scourge-infested underground lair with an escort event and a gong-summon fight — a classic stepping-stone dungeon around level 40.",
        tips = {
            "Ring the gong wave by wave when summoning spiders — clear each wave before ringing again.",
            "Clear every skeleton before engaging Mordresh Fire Eye; the last pack will aggro the boss.",
            "Stacking on the tank greatly reduces the threat of Amnennar's and the Freezing Spirits' AoE abilities.",
            "Interrupts are the keyword of this dungeon: fireballs, heals and Shadow Bolts all need a rotation.",
            "Don't skip the Belnistrasz escort event — great rewards and it culminates in the final boss.",
        },
        entrance = {
            H = "Horde players can travel to the southern part of the Barrens and head east before reaching the Great Lift to find the entrance.",
            A = {
                "Take the boat from Menethil Harbor to Theramore Isle.",
                "Run to the southern part of Dustwallow Marsh and head east before you reach the Great Lift to find the entrance.",
            },
        },
        trash = {
            { title = "Freezing Spirit",
              text = "The is an ethereal mob located throughout RFD. is the key ability of the Freezing Spirits. The strategy to deal with this ability is to stack on the tank in order not to be caught out of position." },
        },
        bosses = {
            { en = "Tuten'kash",
              text = "Tuten'kash is summoned through the spider gong event in RFD. Before you engage him, you will first have to clear a few waves of spiders. After each wave is finished, ring the gong again to summon the next wave. The waves are simple and straightforward, as is Tuten'kash. The tank should face him away from the group to avoid unnecessary web spray, but his other abilities are negligible." },
            { en = "Mordresh Fire Eye",
              text = "Mordresh Fire Eye is a low-armor cast boss that can be bursted down easily by melee dps. Before you engage him, make sure to clear all of the skeletons dancing beside the bone pile. The last pack of skeletons will pull the boss, so make sure to AOE them down quickly to prevent a wipe. Interrupt Mordresh's hard-hitting fireball when you can and this should be an easy win." },
            { en = "Glutton",
              text = "Glutton is a simple tank and spank. Make sure to stay out of his Disease Clouds and be prepared to heal the tank through significant amounts of damage when the boss casts Enrage." },
            { en = "Ragglesnout",
              text = "Ragglesnout's Dominate Mind is by far the most important ability in this encounter. If your tank or healer get MCed, make sure to have your hybrids fill in where needed. Interrupt his heal to prevent a longer encounter and his Shadow Bolts to minimize incoming damage." },
            { en = "Amnennar the Coldbringer",
              text = "Amnennar the Coldbringer is a challenging dungeon boss that should be tanked facing the tent where he stands to neutralize Amnennar's Wrath. Have your group stack on the tank to reduce the severity of Frost Nova, and switch to the spirit that he summons as soon as it spawns. Interrupt Frostbolt and prioritize proper positioning." },
            { en = "Plaguemaw the Rotting",
              text = "Plaguemaw the Rotting is the final boss of an optional escort event. When Belnistrasz begins his ritual, focus down mobs that spawn one at a time, preferably with an offtank pulling adds off Belnistrasz. Plaguemaw is a straightforward tank and spank." },
        },
    },
    uldaman = {
        tagline = "Uldaman is a sprawling titan-archaeology dig site with flexible front/back entrances, golem-heavy pulls and the only Artisan Enchanting trainer in the game.",
        tips = {
            "Golems and sentinels have high armor/HP and DoT immunity — burn them with direct damage instead of DoTs.",
            "Combine the item from the chest behind The Lost Dwarves with Revelosh's drop to summon Ironaya and unlock the hidden chamber.",
            "Annora trains Artisan Enchanting inside the dungeon; enchanters should come stocked with reagents.",
            "Archaedas summons constant non-elite adds — AoE them down; the 4 elite adds at 20% die with him.",
            "Uldaman pulls chain easily, so CC pays off big; tank fights in cleared rooms whenever possible.",
        },
        entrance = {
            H = "Horde groups can fly to Kargath in the Badlands and run to the entrance; without the Kargath flight path, head to Hammerfall in Arathi and travel south through Loch Modan into the Badlands. A back-door tunnel in Dustwind Gulch (east of Hammertoe's Digsite) leads directly into the back of the instance.",
            A = {
                "Alliance groups can fly to Thelsamar in Loch Modan and travel south into the Badlands.",
                "The primary entrance sits just south of the Loch Modan/Badlands border; you'll know you're close when Shadowforge Dwarves start appearing.",
                "A back-door tunnel in Dustwind Gulch, east of Hammertoe's Digsite, provides direct access to the back of the instance.",
            },
        },
        trash = {
            { title = "Digmaster Shovelphlange (Rare)",
              text = "is a level 38 elite goblin that patrols the caverns outside of the instance, in the South Common Hall, before you zone in. He can hit hard, especially for cloth wearers. Make sure the tank picks him up and has aggro before you begin DPSing. Other than a fast attack speed and a couple of abilities, so long as you don't pull any additional mobs, you should be able to burn him down with ease." },
            { title = "Common pulls",
              text = "Many of the pulls in Uldaman will contain groups of enemies. Utilizing crowd control abilities such as , and others will make things much easier. Golem-type mobs have high armor, high HP and are immune to DoT effects." },
            { title = "<Master Enchanter> Annora",
              text = "is the Artisan trainer for Enchanting, located between the Map Chamber and Temple Hall, and easier to get to from the Back Entrance. She's surrounded by scorpids, so be prepared to clear the area before talking with her. You can train Artisan Enchanting from her at level 35 with 200 Enchanting Skill. Come prepared with enough reagents to skill up to 250, at which point you can learn her top recipes , , and so you never have to return." },
        },
        bosses = {
            { en = "Baelog",
              text = "Baelog (level 41 elite), Eric &quot;The Swift&quot; (level 40 elite) and Olaf (level 40 elite) make up The Lost Dwarves. They are friendly to Alliance players but hostile to the Horde. Most groups crowd control Baelog, have the tank pick up Olaf, and burst down Eric &quot;The Swift&quot; as he can cast Intercept on party members, which results in a pesky stun. Once Eric &quot;The Swift&quot; is done for, move on to Olaf while keeping Baelog CC'd. As long as the room is clear, you shouldn't have much trouble. Don't forget to loot the chest behind The Lost Dwarves." },
            { en = "Revelosh",
              text = "Revelosh is a level 40 elite trogg. Revelosh is linked with two Stonevault Rockchewer, so when you pull him, they will also join the battle. You could try to CC one of the Stonevault Rockchewer if you've got it. Otherwise, try to burn down Revelosh as quickly as possible. His Chain Lightning can deal a lot of damage to your party, so take priority in interrupting whenever he gets ready to cast it." },
            { en = "Ironaya",
              text = "Ironaya is a level 40 giant. To summon her, you need to combine the item from the chest behind The Lost Dwarves with a drop from Revelosh, then place the combined item in the model of a city-looking keystone within the next room. She has high armor, lots of HP, is immune to damage-over-time (DoT) effects and can knock players back. Have your tank pick her up and face her away from the rest of the group to avoid her Arcing Smash. Ranged, spread out. Keeping her abilities in mind, it's a fairly straightforward tank & spank type fight." },
            { en = "Obsidian Sentinel",
              text = "Obsidian Sentinel is a level 44 elite golem found right by the Back Entrance. He's got high armor, high HP, and DoT immunity. At 66% and 33% health, he will spawn two non-elite Obsidian Shard. Groups typically kill the two Obsidian Shard first, then return back to the boss." },
            { en = "Ancient Stone Keeper",
              text = "Ancient Stone Keeper is a level 44 elite golem. Like the golem mobs you fought along your way, he's also got high armor, high HP, DoT immunity and a nasty AoE slow & silence ability: Sand Storms." },
            { en = "Galgann Firehammer",
              text = "Galgann Firehammer awaits you with two Shadowforge Geologist by his side. Between these 3 NPCs, there's a lot of AoE magic damage flying around. Tanks, pick up Galgann Firehammer and separate him from the group, keeping him faced away. CC one Shadowforge Geologist, kill the other one, then kill the one that was CC'd. Once both are dead, focus on Galgann Firehammer. His range of fire attacks can be devastating. If able to, dispel any of his fire buffs that he'll cast on your party as they will amplify his fire damage." },
            { en = "Grimlok",
              text = "Grimlok comes with a Stonevault Geomancer, Stonevault Brawler and a Jadespine Basilisk all grouped up together. Many groups will opt to burn down Grimlok as quickly as possible, while CCing one of the adds. Killing Grimlok quickly can result in him dying before being able to cast his group Shrink. After he dies, focus on the Stonevault Geomancer next, and then finish off the remaining 2 adds." },
            { en = "Archaedas",
              text = "Archaedas has a lot of HP and summons non-elite adds throughout the encounter. Make sure your group burns the adds down as quickly as possible. At 20%, he will summon 4 elite adds, who die when he dies. At this point in the fight, many groups opt to burn Archaedas down as quickly as possible. This is a long fight and will require the entire group to perform in order to defeat. Remember to use potions, bandages, cooldowns, and everything you've got!" },
        },
    },
    zul_farrak = {
        tagline = "Zul'Farrak is a classic level-40 troll-city dungeon famous for its stairs event and dense elite packs — AoE and crowd control pay off hugely.",
        tips = {
            "The Shadowhunters' Hex makes the tank drop all aggro — priests should keep Dispel Magic on a handy keybind.",
            "Clear the stairs event wave by wave; on the last wave burn Nekrum down and interrupt Sezz'ziz's heals.",
            "Tank Gahz'rilla with his back to a wall and stack up to avoid being thrown into extra mobs.",
            "Hydromancer Velratha patrols among elite packs — single-pull her before engaging.",
            "For the twin-elite finale, melee stay behind to dodge cleaves and kill Ruuzlu first.",
        },
        entrance = {
            H = "Horde players can travel southeast through Thousand Needles to the Shimmering Flats, then continue south into Tanaris; pick up the flight paths at Freewind Post and Gadgetzan along the way.",
            A = {
                "Take the boat on the left side of the docks in Menethil Harbor to Theramore Isle.",
                "Swim south along the coast to Tanaris to reach the entrance; don't forget the flight paths in Theramore Isle and Tanaris.",
            },
        },
        trash = {
            { title = "Sandfury Shadowhunter",
              text = "The is a Sandfury Troll located inside Zul'Farrak. is the key ability of the Shadowhunters, and if not dealt with properly, will result in a wipe for the group. The Hex ability causes all mobs to drop aggro on the hexxed target, meaning that if the target is the tank, all nearby enemies will begin attacking the remaining members of the group. In order to deal with a Hexxed tank, you must have a priest instantly dispel the effect from the tank. Alternatively, if you have a mage in your group, you can polymorph the Shadowhunter, clear out the remainder of the pack, and deal with the Shadowhunter alone." },
            { title = "The Stairs Event",
              text = "The mid-dungeon stairs event throws several waves of elite trolls at the group. Pace the pulls, clear wave by wave — the final wave spawns Nekrum Gutchewer and Shadowpriest Sezz'ziz." },
        },
        bosses = {
            { en = "Antu'sul",
              text = "Antu'sul is a level 48 elite Sandfury Troll. Antu'sul is a difficult boss due to his ability to summon Sul'lithuz Broodling and Servant of Antu'sul during the encounter. When this happens, all dps should immediately AOE down the additional mobs and prioritize them over the boss. The tank should be ready to interrupt the healing abilities, and melee dps should prioritize totems as soon as they're up. This boss is quite mechanically intensive for a dungeon boss in Vanilla, and requires all parties fulfilling their roles for a successful attempt." },
            { en = "Theka the Martyr",
              text = "Theka the Martyr is a level 46 elite Sandfury Troll, a quest-related mini-boss found in the Scarab room of ZF. At 30%, he becomes immune to physical damage and shadow damage for 30 seconds, making Mages a valuable asset in the dungeon. He is a simple tank and spank, but once he goes immune, he will begin aggroing nearby scarabs to aide him in battle. Focus down Theka first before finishing off the scarabs." },
            { en = "Witch Doctor Zum'rah",
              text = "Witch Doctor Zum'rah is a level 46 elite Sandfury Troll. Zum'rah is a challenging boss that is quite intensive on the healers. Interrupts are paramount during this fight in order to prevent unnecessary damage from his shadow bolt volley. Throughout the engagement, Zum'rah will summon zombies from nearby graves to attack your group. Make sure to switch over to the zombies immediately as they are summoned and burn them down fast. Whenever Zum'rah spawns a totem, prioritize it as well. This is a chaotic fight but if the totem and adds are prioritized, it shouldn't be too difficult." },
            { en = "Nekrum Gutchewer",
              text = "Nekrum Gutchewer and Shadowpriest Sezz'ziz are level 46 and 47 elite Sandfury Trolls who spawn as the last wave of the stairs event in Zul'Farrak. The best strategy to deal with these two is to burn down Nekrum first. He has fewer abilities and is lower level, meaning less chance to dodge/miss/resist spells. Make sure one of your melee interrupts Sezz'ziz's heal in the meantime." },
            { en = "Shadowpriest Sezz'ziz",
              text = "Nekrum Gutchewer and Shadowpriest Sezz'ziz spawn as the last wave of the stairs event in Zul'Farrak. Burn down Nekrum first; he has fewer abilities and is lower level. In the meantime, keep one of your melee on interrupt duty for Sezz'ziz's heal, and switch to Sezz'ziz once his partner is down." },
            { en = "Sergeant Bly",
              text = "Sergeant Bly is a level 45 elite human who is engaged after the stairs event in Zul'Farrak. He is accompanied by several other elite mobs, namely Oro Eyegouge and Murta Grimgut. Between Oro's AOE and Murta's healing, this fight can be quite challenging. Prioritize Oro and Murta before switching to Bly." },
            { en = "Hydromancer Velratha",
              text = "Hydromancer Velratha is a level 46 elite Sandfury Troll located near the end of Zul'Farrak. Velratha is a simple tank and spank, but tests a group's situational awareness. Velratha patrols around the room, which is riddled with elite Sandfury. Make sure that you pull her ALONE, otherwise a wipe is likely. Once you've pulled her safely, interrupt her casts and you should be fine." },
            { en = "Gahz'rilla",
              text = "Gahz'rilla is a level 46 elite Hydra located at the end of Zul'Farrak. He is summoned by using the Mallet on the gong near the aqueduct. Make sure to clear out the room where Gahz'rilla is summoned from. Tank him with the tank's back against a wall and stack on the tank to prevent being thrown up into the air. The rest of the fight is a tank and spank." },
            { en = "Chief Ukorz Sandscalp",
              text = "Chief Ukorz Sandscalp is a level 48 elite Sandfury Troll, and is accompanied by a level 46 elite Ruuzlu. Make sure to face these two away from the group. Melee should stay behind them to avoid the cleave. Kill Ruuzlu first." },
            { en = "Zerillis",
              text = "Zerillis is a level 45 rare-elite Sandfury Troll that patrols throughout Zul'Farrak. Pull him into melee range immediately (you might need to LoS). Simple tank and spank." },
        },
    },
    maraudon = {
        tagline = "Maraudon is a two-wing level-45 dungeon — the orange and purple crystal entrances converge at Earth Song Falls — dropping plenty of Nature Resistance gear.",
        tips = {
            "The orange and purple wings interconnect; once you have the Scepter of Celebras you can open a portal straight to Earth Song Falls.",
            "Elementals and rock-type mobs are DoT-immune with high armor — let direct-damage classes handle them.",
            "Landslide and Princess Theradras both knock back — tank against a wall and keep ranged at max distance.",
            "Prepare tools against the Princess's group Fear in advance (Fear Ward, dispels and the like).",
            "After the Princess, drop into Zaetar's Cave for the final two bosses: Rotgrip and Tinkerer Gizlock.",
        },
        entrance = {
            H = "The Valley of Spears is north of Shadowprey Village and west of the Kodo Graveyard in Desolace; centaurs guard the path, so group up before entering. Two entrances (orange and purple crystal paths) interconnect inside; with the Scepter of Celebras you can open a portal to the base of Earth Song Falls.",
            A = {
                "Alliance players can travel from Nijel's Point west across Desolace to the Valley of Spears entrance.",
                "Centaurs guard the path, so group up before entering.",
            },
        },
        trash = {
            { title = "Shadowshard side trash",
              text = "The Wicked Grotto is the first area you'll discover once zoning in from the purple entrance. You'll encounter an elite and/or mixed in with packs of non-elite who usually attack with ranged abilities. Putridus Shadowstalker usually patrol areas in stealth, so keep an eye out for them! Elementals that roam the area are who use War Stomp and who cast Entangling Roots. The biggest concern on the way to Lord Vyletongue is not pulling any unnecessary additional mobs." },
            { title = "Ambershard side trash",
              text = "Foulspore Cavern is the first area if you zone in from the orange entrance. You'll encounter elite mobs such as and mixed in with packs of non-elite . A works nicely here to help crowd control the elites. As you make your way through the cavern, look for the Larva Spewer to click on to cease the arrival of more larvae, and you'll find Noxxion waiting for you in a pool towards the end." },
            { title = "Earth Song Falls trash",
              text = "wander around and cast a knockback that could throw you into additional mobs — be aware of your surroundings before engaging one. come in linked groups and cannot be pulled one at a time; casters, STAND BACK — they have a nasty AoE silence. patrol areas and split into smaller Theradrim Shardling when killed, sometimes already trailed by Theradrim Shardling. Primordial Behemoth are giants who hit hard and are preferably pulled one at a time." },
        },
        bosses = {
            { en = "Lord Vyletongue",
              text = "Lord Vyletongue is a level 49 elite accompanied by two stealthed Putridus Shadowstalker guards. If the entire group stacks on Lord Vyletongue, you negate his ability to use Auto Shot & Multi-Shot, so have everyone stack close together on the tank. He'll use Blink to get away, so make sure you are quick to stack up again whenever he does so. Most groups DPS Lord Vyletongue down first since he is mobile and can move around the room. Once he's down, finish off his two guards." },
            { en = "Noxxion",
              text = "Noxxion is a level 48 elite and the first boss found in the Ambershard Side. He has an AoE Toxic Volley ability as well as a knockback called Uppercut. After a little while, Noxxion will split into smaller versions of himself. Once they're all defeated, Noxxion will reform, and the fight will continue. Some groups opt to pull him out of the pool, to make killing the adds easier." },
            { en = "Razorlash",
              text = "Continue down Foulspore Cavern and you'll run into Razorlash. Some groups opt to skip this boss encounter, as it isn't mandatory to kill him to advance forward. Razorlash is a level 48 elite and the second boss found in the Ambershard Side. His Puncture causes a painful DoT (damage over time) tick for 10 seconds, and an AoE Cleave ability for those in melee range. Therefore, casters should stand at max range while burning him down." },
            { en = "Meshlok the Harvester",
              text = "Meshlok the Harvester is a level 48 elite, rare spawn inside Poison Falls who patrols the waters near the beginning and looks very similar to either a Cavern Lurker or Cavern Shambler, so make sure you hover your mouse or use a /tar Meshlok macro to check to see if he is spawned. If he is not, Cavern Shambler will patrol in his place. He isn't very challenging. Tanks, tank him away from the group. Ranged, spread out if possible to avoid his War Stomp, and healers, be aware that he can interrupt your spell casting with Earth Shock." },
            { en = "Celebras the Cursed",
              text = "Celebras the Cursed is a level 49 elite found at the end of Poison Falls. He summons non-elite Corrupt Force of Nature to constantly spawn during the encounter. He will most often use his Wrath spell, which can be interrupted, so make sure it's getting interrupted as often as possible. If one of his Corrupt Force of Nature falls, he will summon another one. Focus down Celebras the Cursed first, then polish off the remaining Corrupt Force of Nature." },
            { en = "Landslide",
              text = "Landslide is a level 50 elite Behemoth found in Poison Falls. He has many similar abilities to the Primordial Behemoth that you fought on the way to his alcove. Keep him near the area in which he stands. Tanks, tank him with your back to a wall. Ranged, stay at max distance to avoid any knockback or stun from the Theradrim Shardling, who despawn once Landslide dies." },
            { en = "Rotgrip",
              text = "Rotgrip is a giant level 50 white crocolisk elite found in Poison Falls. He patrols in the water of Zaetar's Cave — the area in which you just defeated Princess Theradras. Drop down into the water to engage him. Be sure the surrounding area is clear, as there are also lingering Hydras in the water. He hits hard! Make sure your tank has proper aggro before everyone else engages. Healers, try your best to keep your tank and other party members topped off. Rotgrip can dish out devastating damage quickly using his two abilities: Puncture, a physical damage-over-time, and Fatal Bite." },
            { en = "Tinkerer Gizlock",
              text = "Tinkerer Gizlock is a level 50 elite goblin found in Poison Falls. Tanks, face him away from the group to prevent group damage from his Goblin Dragon Gun. Everyone else — stack close together in melee range. This will prevent Tinkerer Gizlock from being able to use his ranged abilities. With this strategy in mind, he shouldn't be difficult to burn down." },
            { en = "Princess Theradras",
              text = "Although considered the final boss, most groups will head to Princess Theradras after killing Landslide, and then jump down to kill Rotgrip and Tinkerer Gizlock after. You'll fight more groups of Primordial Behemoth before encountering Princess Theradras, this time in packs of 2 — focus down one at a time. Princess Theradras is a level 51 elite found in Poison Falls. She is not an easy fight, so understanding her mechanics is vital. Groups tend to engage her towards the back of her cavern to allow for more space. She has a group of Fear called Repulsive Gaze; Fear Ward, Berserker Rage & Tremor Totem are all spells to help with this effect. She also has a pesky group knockback ability, Dust Field, which not only pushes you back but damages as well — at max range, non-melee players should be able to avoid this. Also, be aware that there are non-aggressive turtles in the area around her cavern: if they get hit with a spell, they will aggro on you, so be mindful of your surroundings." },
        },
    },
    sm_graveyard = {
        tagline = "The easiest of Scarlet Monastery's four wings, full of mindless undead packs — recommended for levels 26-36.",
        tips = {
            "Graveyard mobs are around level 30-32, grouped in packs of 2-4. Just don't let any stray mob run away and aggro additional packs, and you'll be fine.",
            "Three rare spawns (Azshir the Sleepless, Fallen Champion, Ironspine) have roughly a 5% chance to be up. An isolated Unfettered Spirit marks a spawn point — kill the lone undead nearby and they respawn every 10-15 minutes.",
            "Many players solo this wing at higher levels to farm gold, so the pace can be quite fast.",
        },
        entrance = {
            H = "From the Undercity, simply follow the path northeast through Tirisfal Glades and you'll reach the monastery. From Orgrimmar, take Frezza <Zeppelin Master>'s zeppelin to the Undercity. The Graveyard entrance is the open doorway on the far left of the monastery hallway.",
            A = {
                "The most common path starts at Southshore in Hillsbrad Foothills: head north along the road, cut through the pass between the Dalaran Crater and the Ruins of Alterac, swim north through Lordamere Lake and surface at the border of Silverpine Forest and Tirisfal Glades.",
                "From there follow the main road northeast through Tirisfal Glades to the monastery. If you're 40+ with a mount, you can alternatively travel from Western Plaguelands and run west into Tirisfal Glades — be careful, you'll cross right by the Horde encampment called the Bulwark.",
            },
        },
        trash = {
            { title = "Undead packs",
              text = "Graveyard trash comes in undead packs of 2-4. Tank them steadily and above all prevent runners — one escaping mob can snowball into the next pack." },
        },
        bosses = {
            { en = "Interrogator Vishas",
              text = "Interrogator Vishas doesn't involve much strategy. He's usually pulled with one additional humanoid, but as long as no additional mobs are aggro'd during the encounter, it's a straightforward tank and spank fight. Watch out for his DoT abilities. Abilities: Immolate" },
            { en = "Azshir the Sleepless",
              text = "Azshir the Sleepless has several magic abilities, including a fear. Make sure the area is clear before engaging him, as the fear can lead someone into additional mobs. Be wary of his Call of the Grave, which can inflict damage even after his death. Abilities: Call of the Grave Soul Siphon Terrify" },
            { en = "Fallen Champion",
              text = "The Fallen Champion encounter is straightforward, consisting of cleaving melee attacks. All DPS should stand behind him to avoid his Cleave. Abilities: Berserker Stance Cleave" },
            { en = "Ironspine",
              text = "Ironspine is a simple tank and spank encounter. Healers, keep an eye on your party's health when Ironspine casts Poison Cloud, as it can deal quite a bit of damage. Abilities: Curse of Weakness Poison Cloud" },
            { en = "Bloodmage Thalnos",
              text = "Bloodmage Thalnos mostly casts spells, so it will be a heavy magic damage fight. He casts several AoE magic abilities in his close proximity, so ranged should keep their distance and healers should keep a close eye on the tank and melee. Abilities: Shadow Bolt Flame Spike Fire Nova" },
        },
    },
    sm_library = {
        tagline = "The second wing of Scarlet Monastery, recommended for levels 29-39; Arcanist Doan drops the Scarlet Key to the Armory and Cathedral.",
        tips = {
            "Line of sight pulling is very useful in the Library — the pesky caster mobs come closer to you instead of aggro'ing additional mobs.",
            "As with all caster mobs, interrupting their casts helps your party greatly.",
            "Watch out for mobs that run away at low health: use snares, slows and stuns to stop them — runners are the main cause of wipes here.",
            "Mobs respawn in Scarlet Monastery if you're too slow after a wipe, so keep a moderate pace.",
        },
        entrance = {
            H = "From the Undercity, simply follow the path northeast through Tirisfal Glades and you'll reach the monastery. From Orgrimmar, take Frezza <Zeppelin Master>'s zeppelin to the Undercity. The Library entrance is the open doorway on the far right of the monastery hallway.",
            A = {
                "The most common path starts at Southshore in Hillsbrad Foothills: head north along the road, cut through the pass between the Dalaran Crater and the Ruins of Alterac, swim north through Lordamere Lake and surface at the border of Silverpine Forest and Tirisfal Glades.",
                "From there follow the main road northeast through Tirisfal Glades to the monastery. If you're 40+ with a mount, you can alternatively travel from Western Plaguelands and run west into Tirisfal Glades — be careful, you'll cross right by the Horde encampment called the Bulwark.",
            },
        },
        trash = {
            { title = "Library trash",
              text = "Library mobs average level 33-35, a mix of melee and casters. LoS pulling, interrupting casts and stopping runners are the three most important things." },
            { title = "Notable mobs",
              text = "— can self heal and cast ; — casts Fireball; — melee only, can Kick casters." },
        },
        bosses = {
            { en = "Houndmaster Loksey",
              text = "Houndmaster Loksey, the first boss you'll encounter, is accompanied by 3 elite Scarlet Tracking Hound. The hounds can be crowd controlled with anything that works on beasts, such as Polymorph. A general strategy: crowd control one of the hounds, have the tank keep Houndmaster Loksey busy while the DPS kill the hounds, then focus down Houndmaster Loksey. Be aware that he will Bloodlust at low health. Abilities: Sword Finesse Battle Shout Bloodlust" },
            { en = "Arcanist Doan",
              text = "Tank Arcanist Doan in the middle of the room with the ranged spread to the edges. When he casts Detonation, everyone must run as close to the edges as possible. Healers, keep up heals on the group when he casts Arcane Explosion and be wary of his Silence. Some groups opt to bring Arcanist Doan into the center of the previous hall and use the pillars to LoS his Detonation. Don't forget to pick up the key from the chest in his chamber after you kill him — it's required to access the Armory and the Cathedral. Abilities: Arcane Bubble Arcane Explosion Detonation Polymorph Silence" },
        },
    },
    sm_armory = {
        tagline = "A short wing with a single boss, Herod, recommended for levels 32-42 — a step up in difficulty from the Library.",
        tips = {
            "Armory mobs range from level 32-42, and most pulls contain at least two or three mobs — use crowd control when needed.",
            "Mobs run away at low health: use snares, stuns and whatever you can to stop a runner from bringing back friends.",
            "There are quite a few patrols — watch out for packs moving around the halls before you pull.",
        },
        entrance = {
            H = "From the Undercity, simply follow the path northeast through Tirisfal Glades and you'll reach the monastery. From Orgrimmar, take Frezza <Zeppelin Master>'s zeppelin to the Undercity. The Armory door is locked (requires the Scarlet Key from Arcanist Doan) and is the second door from the right, just left of the Library entrance.",
            A = {
                "The most common path starts at Southshore in Hillsbrad Foothills: head north along the road, cut through the pass between the Dalaran Crater and the Ruins of Alterac, swim north through Lordamere Lake and surface at the border of Silverpine Forest and Tirisfal Glades.",
                "From there follow the main road northeast through Tirisfal Glades to the monastery. If you're 40+ with a mount, you can alternatively travel from Western Plaguelands and run west into Tirisfal Glades — be careful, you'll cross right by the Horde encampment called the Bulwark.",
            },
        },
        trash = {
            { title = "Armory trash",
              text = "Most pulls contain two or three mobs at a time, runners are common and patrols frequent — scout the halls before engaging." },
            { title = "Notable mobs",
              text = "— casts , comes with a fire elemental pet; — standard melee, can ; — casts and ; — standard melee that can ; — hits hard and Enrage at low HP; — paladin type, can cast Heal; — standard melee." },
        },
        bosses = {
            { en = "Herod",
              text = "坦克把他拉在房间中央，远程分散站到楼梯上。当他施放旋风斩时会开始旋风斩、喊出\"圣光之刃！\"并免疫法术。房间中央附近的人必须立刻跑开，否则会被打出毁灭性的伤害——绝不要试图硬抗。远程一开始就站在楼梯上会更轻松。当赫洛德 &lt;血色十字军勇士&gt;死后全队集合，会有超过 20 只非精英血色预备兵冲进房间，范围技能清掉即可。技能：顺劈斩 狂怒 急速冲锋 旋风斩" },
        },
    },
    sm_cathedral = {
        tagline = "The final and toughest wing of Scarlet Monastery, recommended for levels 35-45 — home to the Mograine & Whitemane encounter.",
        tips = {
            "Many of the mob packs in the Cathedral are grouped very closely together, so pull each pack carefully to prevent runners.",
            "Line of sight pulling is essential for the tank here, especially once you clear the courtyard and approach the entrance of the Chapel itself.",
            "Don't rush into the Chapel: slowly pull the mobs outside first. Once inside, clear every pack before engaging the bosses — pulling the boss prematurely aggroes every remaining mob, including the packs beside the altar.",
        },
        entrance = {
            H = "From the Undercity, simply follow the path northeast through Tirisfal Glades and you'll reach the monastery. From Orgrimmar, take Frezza <Zeppelin Master>'s zeppelin to the Undercity. The Cathedral door is locked (requires the Scarlet Key) and is the second door from the left, just right of the Graveyard entrance.",
            A = {
                "The most common path starts at Southshore in Hillsbrad Foothills: head north along the road, cut through the pass between the Dalaran Crater and the Ruins of Alterac, swim north through Lordamere Lake and surface at the border of Silverpine Forest and Tirisfal Glades.",
                "From there follow the main road northeast through Tirisfal Glades to the monastery. If you're 40+ with a mount, you can alternatively travel from Western Plaguelands and run west into Tirisfal Glades — be careful, you'll cross right by the Horde encampment called the Bulwark.",
            },
        },
        trash = {
            { title = "Cathedral trash",
              text = "Packs are dense and runners common; the tank should LoS-pull heavily. Clear the outside completely before entering the Chapel." },
            { title = "Notable mobs",
              text = "— priest-like, can and Heal; — standard melee, casts ; — melee, high damage attack ; — caster type with Arcane Explosion & ." },
        },
        bosses = {
            { en = "High Inquisitor Fairbanks",
              text = "Not a particularly challenging fight; he is found lying on the ground until you engage him. He casts Curse of Blood on a party member that can be dispelled. Watch out for him also casting Fear and Sleep on party members, as well as Power Word: Shield on himself. Interrupt his Heal and you've got him. Abilities: Curse of Blood Heal Power Word: Shield Sleep" },
            { en = "Scarlet Commander Mograine",
              text = "He's your typical paladin-type boss. Watch out for his Hammer of Justice and his ability to Divine Shield. After you defeat him, High Inquisitor Whitemane will run out from behind the altar and that fight will begin. Abilities: Retribution Aura Hammer of Justice Crusader Strike Lay on Hands Divine Shield" },
            { en = "High Inquisitor Whitemane",
              text = "High Inquisitor Whitemane mainly casts Holy Smite - Spell - Classic World of Warcraft as her primary attack. After you get her health down to a certain point, she'll cast an unavoidable group Sleep on your party, allowing her to cast Scarlet Resurrection on Scarlet Commander Mograine and heal both back to full health. Have your tank pick up Scarlet Commander Mograine, burn down High Inquisitor Whitemane, then finish off Scarlet Commander Mograine. Some groups may kill her before she uses Scarlet Resurrection, but then the party will be unable to loot Scarlet Commander Mograine. Abilities: Holy Smite Heal Deep Sleep Power Word: Shield Scarlet Resurrection" },
        },
    },
    scholomance = {
        tagline = "A school of necromancy on Caer'Darrow island in Western Plaguelands — a level 55-60 dungeon with a boss in each of six rooms, ending with Darkmaster Gandling.",
        tips = {
            "Scholomance is full of humanoid and undead mobs — crowd control (Polymorph, Shackle Undead, Fear undead, etc.) makes the run much smoother.",
            "复活的尸体被\"杀掉\"约 10 秒后会重新站起来，做好它们再爬起来咬你的准备。",
            "Plagued Ghouls spew a poison cloud when they die, dealing about 350 nature damage per second — clear the area around the corpse immediately.",
            "The entrance gate is locked: get in with the Scholomance key, a Large Seaforium Charge (Engineering 275), a rogue with 280+ lockpicking, or have someone inside open it with the torch.",
            "Bring someone who can dispel curses — several boss fights rely on it, especially the Barov couple.",
        },
        entrance = {
            H = "Horde players can travel from Light's Hope Chapel or Tarren Mill to Western Plaguelands; the instance entrance is behind a locked gate at the back of the Scholomance building on Caer'Darrow island.",
            A = {
                "Alliance can travel from Aerie Peak, Chillwind Point or Light's Hope Chapel to Caer'Darrow island in Western Plaguelands.",
                "The gate is locked; there are four ways in: a party member with the Key to Scholomance, a Large Seaforium Charge (Engineering 275), a rogue with 280+ lockpicking, or having someone open the gate from the inside using the torch.",
            },
        },
        trash = {
            { title = "Reanimated Corpse",
              text = "是学院里的亡灵小怪。注意：它们被\"杀掉\"约 10 秒后会从地上重新站起来，做好再战一场的准备！" },
            { title = "Risen Aberration",
              text = "The is an undead, skeletal trash mob. Note: are immune to non-Holy magic." },
            { title = "Plagued Ghoul",
              text = "The is an undead trash mob. Note: spews a poison cloud when it dies that deals about 350 nature damage per second — clear the area around the corpse; the cloud itself marks the safe distance." },
        },
        bosses = {
            { en = "Blood Steward of Kirtonos",
              text = "Blood Steward of Kirtonos is a level 57 elite located in the Reliquary. She has a few curses that can be dispelled. Watch out for her Paralyzing Poison as it stuns the target for 8 seconds. With those two things in mind, DPS her down! Abilities: Curse of Impotence Curse of Weakness Paralyzing Poison" },
            { en = "Kirtonos the Herald",
              text = "Kirtonos the Herald is a level 60 elite located out on the porch; he can only be summoned if someone in your group has the summoning item. Tank, grab aggro and keep your back to a wall to prevent knockback. In human form, Kirtonos the Herald uses his caster abilities — have someone dispel the curse, especially if it's on your healer. Once Kirtonos the Herald transforms into his gargoyle form, it becomes a tank and spank fight so long as your tank maintains aggro. Abilities: Curse of Impotence Curse of Weakness Paralyzing Poison" },
            { en = "Jandice Barov",
              text = "Jandice Barov is a level 61 elite who is found by using a torch on the south wall. Jandice Barov will create several copies of herself that spread throughout the room. You can't AoE them down, so you must target them down individually. Some parties opt to ignore the adds and just focus down Jandice herself. Remember to have someone dispel her Curse of Blood. Abilities: Curse of Blood Banish" },
            { en = "Rattlegore",
              text = "Rattlegore is a level 61 elite located in the Great Ossuary's Basement. Pull Rattlegore once your surrounding area is clear. His abilities are melee focused, and he hits like a truck! Ranged, keep back as far as possible. Tank, face Rattlegore away from the group. Armor reducing abilities such as Sunder Armor or Expose Armor can help your team take him down quicker. Abilities: Knock Away Strike War Stomp Sunder Armor Expose Armor" },
            { en = "Marduk Blackpool",
              text = "Marduk Blackpool is a level 58 elite located in the Viewing Room. Tanks should hold Marduk Blackpool in place while ranged stand back, ensuring they are not affected by his Defiling Aura. Melee, watch out for his Shadow Shield — it deals damage each time you attack him as long as it's active. Other than those two factors, he's pretty easy to burn down. Abilities: Cleave Defiling Aura Shadow Shield" },
            { en = "Vectus",
              text = "Vectus is a level 60 elite located in the Viewing Room. Vectus is a pretty squishy target with fire-based spells. Watch out for his AoE abilities: don't stand in the fire and you'll DPS him down pretty quickly. Abilities: Blast Wave Flamestrike" },
            { en = "Ras Frostwhisper",
              text = "Ras Frostwhisper is a level 60 elite located along the passage through the Viewing Room. Make sure the entire area surrounding Ras Frostwhisper is clear before engaging. He has several frost-type magic spells and abilities. Tank, face him away from the group, watch out for his Fear and plan an interrupt rotation to minimize his spell casting. Abilities: Chill Nova Frost Armor Fear Freeze Frostbolt Volley" },
            { en = "Instructor Malicia",
              text = "Instructor Malicia is a level 60 elite located in the southern room on the upper floor. Instructor Malicia has a few heals at her disposal, so be sure to sort out an interrupt rotation to minimize her casting. Have someone dispel her Call of the Grave curse and DPS her down. Abilities: Call of the Grave Corruption Heal Renew Slow" },
            { en = "Doctor Theolen Krastinov",
              text = "Doctor Theolen Krastinov is a level 60 elite located in the eastern room on the upper level (The Hall of the Damned). Have your tank pull Doctor Theolen Krastinov and keep their back to a wall. At 50% health, his attack speed will dramatically increase — a great time to use defensive and healing cooldowns. He has melee-only abilities, so keep the tank alive and burn him down! Abilities: Knock Away Rend" },
            { en = "Lorekeeper Polkelt",
              text = "Lorekeeper Polkelt is a level 60 elite located in the northern room on the upper level. Lorekeeper Polkelt has several toxic AoE abilities that are damaging when nearby. One strategy to keep him at max range: have someone in your party pull Lorekeeper Polkelt and jump off the upper-level railing, and as Lorekeeper Polkelt runs around the stairs, your tank picks him up on the lower level. The rest of the party, remaining on the upper level, can attack him safely without worrying about his AoE abilities. If anyone is infected with his Volatile Infection, make sure they spread out from the group. Abilities: Corrosive Acid Noxious Catalyst Volatile Infection" },
            { en = "The Ravenian",
              text = "The Ravenian is a level 60 elite located in the southern room on the lower level (The Barov Family Vault). The Ravenian should be tanked against a wall, facing away from the rest of the group. It's a melee-centric fight, and he hits pretty hard and fast. Watch out for his AoE abilities and make sure the tank has generated enough threat before engaging. Abilities: Cleave Knock Away Sundering Cleave Trample" },
            { en = "Lord Alexei Barov",
              text = "Lord Alexei Barov is a level 60 elite located in the eastern portion of the lower level (The Barov Family Vault) and is considered one of the toughest bosses in Scholomance. Two skeletal bodyguards accompany him; they hit pretty hard but can be CC'd with Shackle Undead or Turn Undead. The room he's in has toxic green liquid on the floor that you must not stand in. His AoE aura Unholy Aura constantly ticks damage to anyone in range, so tanks must pull Alexei back at max range so the aura doesn't afflict the rest of the group. His Veil of Shadow can be very hard on the group if not cleansed: if you can't cleanse the curse, healers, keep the tank topped off as best you can — when Veil of Shadow strikes, you'll have a lot of difficulty healing your tank for 15 seconds. Abilities: Immolate Unholy Aura Veil of Shadow Shackle Undead Turn Undead" },
            { en = "Lady Illucia Barov",
              text = "Lady Illucia Barov is a level 60 elite located in the northern room of the lower level (The Barov Family Vault). The biggest concern with fighting Lady Illucia Barov is her ability to Dominate Mind, a mind control mechanic. Be sure to stun or CC whoever is afflicted with Dominate Mind. She can also cast an AoE Silence and Fear, so make sure her entire area is clear before engaging. Abilities: Bane of Agony Dominate Mind Fear Silence Shadow Shock" },
            { en = "Darkmaster Gandling",
              text = "Darkmaster Gandling is a level 61 elite located in the center of The Barov Family Vault, and spawns once you kill the last of the previous six bosses — so don't stand in the center and prematurely aggro him. Many tanks keep Darkmaster Gandling in the center where he spawns while the ranged stay atop the stairs. He'll periodically teleport a player to an adjacent room, where they are locked in until they defeat the enemies inside — be prepared in case your tank or healer gets teleported. An interrupt order works nicely for Arcane Missiles. Have someone dispel Improved Shadow Bolt - Spell - Classic World of Warcraft as quickly as possible. Other than that, he has a lot of HP, so execute the mechanics properly and you'll be rewarded! Abilities: Arcane Missiles Curse of the Darkmaster Shadow Shield Improved Shadow Bolt - Spell - Classic World of Warcraft" },
        },
    },
    sunken_temple = {
        tagline = "Descend into the Temple of Atal'Hakkar and stop the Atal'ai from summoning the Blood God.",
        tips = {
            "Clear the lower level and balcony minibosses before pushing into the central pool area.",
            "Atal'ai priests heal their allies - interrupt or kill them first.",
            "Summoning the Avatar of Hakkar requires the quest chain - make sure someone can summon.",
            "Respawns are quick in the dragon areas - avoid pulling extra packs.",
        },
        entrance = {
            H = "Fly to Hammerfall in Arathi Highlands and run into the Swamp of Sorrows to Stonard.Head west from Stonard to the Temple of Atal'Hakkar area.Swim across the moat and enter from the submerged entrance.",
            A = {
                "From Stormwind, travel through Duskwood and Deadwind Pass into the Swamp of Sorrows; the Alliance camp Watch Tower is on the west side.",
                "Head east from Watch Tower to the temple.",
                "Swim across the moat and enter from the submerged entrance.",
            },
        },
        trash = {
            { title = "Atal'ai Priests",
              text = "They heal their allies - interrupt or focus them down first to keep trash fights short." },
            { title = "Dragonkin Packs",
              text = "Dragonkin come in pairs and call reinforcements - pull pack by pack." },
        },
        bosses = {
            { en = "Avatar of Hakkar",
              text = "Head to the west side of the Pit of Sacrifice and you’ll enter the Sanctum of the Fallen God . Clear the trash along the way and to prepare for the encounter. Avatar of Hakkar, a level 48 elite, cannot be summoned unless someone in your group has from the quest OR, has already completed the aforementioned quest and has , which allows the player to summon Hakkari Bloodkeeper without the egg. Kill the adds until a Hakkari Bloodkeeper spawns. Kill it and grab the from the corpse. Groups usually keep Free-for-All loot on in this encounter so one designated person can loot the bloods. (Don't forget to switch it back after Hakkar spawns!) Using the blood, you can extinguish one of the four braziers in the room. Proceed until another Hakkari Bloodkeeper spawns, and all of the braziers are extinguished. If everyone moves close to a wall before extinguishing the final brazier, you can drop combat before engaging the Avatar of Hakkar. The fight itself is pretty straightforward. He'll cast Cause Insanity on a random player. The best strategy is to stun or CC that player until they're returned to normal. If possible, Dispel Shadow Word: Pain - Spell - Classic World of Warcraft, too. Otherwise, DPS him down and prepare for victory!" },
            { en = "Jammal'an the Prophet",
              text = "Now that all 6 Atal'ai Defenders are dead, the way to Jammal'an the Prophet is now open. Head on back towards the start of the instance and head left." },
            { en = "Ogom the Wretched",
              text = "Now that all 6 Atal'ai Defenders are dead, the way to Jammal'an the Prophet is now open. Head on back towards the start of the instance and head left." },
            { en = "Dreamscythe",
              text = "After Jammal'an the Prophet has fallen, the two drakes Weaver & Dreamscythe will spawn in the Pit of Sacrifice . They’re relatively easy to burn down. Tanks should tank with their backs to a wall, keeping the drakes facing away from the party to avoid their frontal cone and knockback abilities." },
            { en = "Weaver",
              text = "After Jammal'an the Prophet has fallen, the two drakes Weaver & Dreamscythe will spawn in the Pit of Sacrifice . They’re relatively easy to burn down. Tanks should tank with their backs to a wall, keeping the drakes facing away from the party to avoid their frontal cone and knockback abilities." },
            { en = "Hazzas",
              text = "After killing Weaver & Dreamscythe, two more drakes, Hazzas & Morphaz, will spawn in the hallway right outside the Chamber of the Dreamer . Fighting Hazzas and Morphaz is the same strategy as the previous two drakes. Try not to pull both at the same time and avoid any trash in the area. These are the last two big kills before Shade of Eranikus." },
            { en = "Morphaz",
              text = "After killing Weaver & Dreamscythe, two more drakes, Hazzas & Morphaz, will spawn in the hallway right outside the Chamber of the Dreamer . Fighting Hazzas and Morphaz is the same strategy as the previous two drakes. Try not to pull both at the same time and avoid any trash in the area. These are the last two big kills before Shade of Eranikus." },
            { en = "Shade of Eranikus",
              text = "Shade of Eranikus, a level 55 elite, will summon any leftover dragonkin in the instance to his side, so it’s important to make sure you’ve cleared them all before pulling the boss. Ranged, stay out of melee range to avoid his AoE stun ability, War Stomp. The target with the highest threat will get afflicted with Deep Slumber. Players can use anti-aggro abilities such as Fade, Blessing of Salvation and Feint to help control who gets afflicted with Deep Slumber. Melee, never stand in front of the boss and be wary of his War Stomp ability. DPS him down following the mechanics and you’ll be fine. It’s a long fight so healers, be sure to keep an eye on your mana pool!" },
        },
    },
    blackrock_depths = {
        tagline = "The largest classic dungeon: through the Dark Iron capital to Emperor Dagran Thaurissan.",
        tips = {
            "The Shadowforge Key is essential - get it on your first run to unlock the shortcut doors.",
            "Split BRD into two runs: the first half and the Emperor half.",
            "Buy ale in the Grim Guzzler to trigger Phalanx and smash the door open.",
            "The Ring of Law arena picks a random combatant - all six strategies are covered here.",
            "Lava Run groups can pick up Incendius and Fineous Darkvire on the way.",
        },
        entrance = {
            H = "From Kargath in the Badlands, run west into Blackrock Mountain.Follow the inner ring down to the lower central platform; the entrance is by the Detention Block.Without the Shadowforge Key, fight through the main hallway; with it, open the side doors.",
            A = {
                "Fly to Morgan's Vigil in Burning Steppes (or run via Duskwood).",
                "Enter Blackrock Mountain and take the inner ring down to the central platform entrance.",
                "The key quest chain also starts from the Burning Steppes side.",
            },
        },
        trash = {
            { title = "Dark Iron Camps",
              text = "Dark Irons come in dense packs with patrols - pull carefully and use fear sparingly." },
            { title = "Core Hounds & Fire Elementals",
              text = "Found along lava halls; they cast fire spells - fire resistance helps a lot." },
        },
        bosses = {
            { en = "Lord Roccor",
              text = "Arguably, Lord Roccor is one of the easiest bosses in . Level 60 druids are able to solo this boss, which indicates just how easily he can be defeated. Lord Roccor is incredibly easy. There is nothing really to look out for. Earth Shock can interrupt casting, which is about the only real concern on this boss." },
            { en = "High Interrogator Gerstahn",
              text = "High Interrogator Gerstahn is the first boss many will face their first time in ! She is not exceedingly difficult overall, but can cause problems if you don't compensate for some of her mechanics. Killing her is necessary to obtain the , which is used to complete quests in the Detention Block . Overall, the approach to beating her is fairly simple. Her use of Psychic Scream is the most challenging part of the encounter as it can lead to other packs being pulled. For Horde Shamans, use tremor to deal with the fear. For Alliance Dwarf Priests, use fear ward. Further, warrior tanks can attempt Berserker Rage, but the inability to effectively time and predict the fear makes utilizing this more about luck than timing. As for other tank/healer combinations and for DPS, attempt to wedge yourself deeply in a corner to attempt to mitigate some of the fear effects. Apart from the fear, dispel Shadow Word: Pain and interrupt the Mana Burn." },
            { en = "Houndmaster Grebmar",
              text = "Houndmaster Grebmar is another fairly easy boss fight. He shouldn't cause issues as long as he is handled appropriate to his patrol path. Houndmaster Grebmar pats around the room between two packs of hounds. Kill the pack of hounds opposite of his patrol path. Then, when he pats back, kill the other pack. Once both packs are dead." },
            { en = "Ring of Law: Gorosh the Dervish",
              text = "Gorosh the Dervish is like a warrior with Whirlwind and Mortal Strike. Maximize healing output outside of the Mortal Strike debuff. It is an easy fight as long as healer can sustain through the use Mortal Strike." },
            { en = "Ring of Law: Grizzle",
              text = "Grizzle is incredibly easy. There is nothing really to look out for. Earth Shock can interrupt casting, which is about the only real concern on this boss." },
            { en = "Ring of Law: Eviscerator",
              text = "Eviscerator is more annoying than difficult. Shadow Bolt Volley can be rather annoying, but it shouldn't kill the group. That said, priests can utilize Shadow Protection to their advantage here. The additional shadow resistance makes the fight trivial." },
            { en = "Ring of Law: Ok'thor the Breaker",
              text = "Ok'thor the Breaker is the most difficult boss within Ring of the Law because of the number of abilities. He plays like a mage, and bad Polymorph luck could lead to a wipe. The key is to dispel the Polymorph and have as many members stay at range as possible to minimize the effect of Arcane Explosion" },
            { en = "Ring of Law: Anub'shiah",
              text = "Anub'shiah is almost as difficult as Ok'thor the Breaker. Curse of Tongues and Enveloping Web both need an immediate dispel. These are the difficult mechanics. The rest aren't too tricky. No real strategy needed other than the dispels." },
            { en = "Ring of Law: Hedrum the Creeper",
              text = "Hedrum the Creeper is a fairly straightforward boss. No real strategy is present outside of cleansing the poisons and dispel the Immobilize." },
            { en = "Pyromancer Loregrain",
              text = "Pyromancer Loregrain is an optional boss that spawns near the Shrine. It is an incredibly easy fight. Skipped unless farming . Pyromancer Loregrain does not really warrant discussion of strategy outside of destroying to totem. Incredibly easy boss to kill." },
            { en = "Warder Stilgiss",
              text = "Warder Stilgiss spawns with Verek. The fight is not difficult for a five man group. Just kill Warder Stilgiss first and then Verek next." },
            { en = "Verek",
              text = "Warder Stilgiss spawns with Verek. The fight is not difficult for a five man group. Just kill Warder Stilgiss first and then Verek next." },
            { en = "Fineous Darkvire",
              text = "Fineous Darkvire is an optional boss once you complete the quest required to kill him. As such, many groups opt to avoid him because it is a pain trying to clear all of the adds to reach him. Fineous Darkvire is a rather straightforward boss. He hits incredibly hard and has a healing mechanic. As such, it is important to interrupt the heal and for healers to pre-cast heals to keep up with the damage output. Further, when poorly geared, it is important to make sure all the adds along the pathway are killed to avoid an accidental aggro causing a wipe." },
            { en = "Lord Incendius",
              text = "Lord Incendius is an optional boss, but most groups (even those doing Lava Runs ) tend to grab him as he is an easy kill. He is also located by the Black Anvil, needed by Blacksmiths . Lord Incendius is not difficult, but tanks and group members need to make sure they don't get knocked off the platform because there is no getting back up outside of dying." },
            { en = "Bael'Gar",
              text = "Bael'Gar is an optional boss that most groups skip because he is not important to the advancement of the dungeon. Bael'Gar spawns adds, which needs to be kill. Also, tanks need to face Bael'Gar away from the group Magma Splash is not a major concern if that is done. Outside of the tank taking a lot of damage, this fight is fairly easy." },
            { en = "General Angerforge",
              text = "General Angerforge is an optional boss, but a lot of players will want to farm it for and . Overall, the fight is fairly difficult because of the adds. If your group is lacking on AoE damage, the fight is harder than it would otherwise be. General Angerforge is straightforward. He behaves like a warrior, and then calls adds during the encounter. Just burn him and AoE the adds when they come. They have fairly low health, so they die fairly easily." },
            { en = "Golem Lord Argelmach",
              text = "Golem Lord Argelmach is an another optional boss that most avoid after the first few runs. It is one of the more challenging fights in , which is one reason why many avoid the fight all together. The primary reason to enter this room is for the , which is near Golem Lord Argelmach. Every raid will want an engineer who is able to craft this item, so be prepared to visit a lot. Golem Lord Argelmach is a difficult fight because of Chain Lightning. It is an unrelenting amount of damage if you're group is stacked too close together. As such, the real key to this fight is remaining spread out so that Chain Lightning doesn't freely bounce from target to target, which is the major killing mechanic on this fight." },
            { en = "Guzzler",
              text = "There are a series of encounters in The Grim Guzzler that are covered in the Blackrock Depths Quest Guide , so I won't spend a great deal of time covering the minor encounters, such as and . However, Phalanx will be discussed as it is the primary encounter within The Grim Guzzler. The Grim Guzzler is a bar in Blackrock Depths featuring neutral patrons as well as the vendors Plugger Spazzring and Lokhtos Darkbargainer. However, you may want to get into barfights with the patrons to complete quests or kill bosses." },
            { en = "Phalanx",
              text = "To get through the room quickly just buy 6 from Plugger Spazzring to give to Private Rocknot. After three turn-ins of to Private Rocknot, he will start to rage. This action causes Phalanx to activate to stop Private Rocknot. The door to the remainder of the dungeon is smashed open during the scuffle. Phalanx hit fairly hard with Mighty Blow, but this does not warrant a lengthy strategy discussion. The group may be tempted to throw these bottles at patrons as the tool tip explains, but refrain from doing this as they will become angry. The other method to reach the next room past the Grim Guzzler is not as easy. This involves doing , which allows Nagmara to seduce Rocknot." },
            { en = "Ambassador Flamelash",
              text = "Ambassador Flamelash is a DPS race is some sense. There are adds that spawn which rush to the boss. If they reach the boss, he gets a buff. However, these adds can easily be killed before reaching him. As such, the way to beat him is to kill the adds before they reach him and increase his damage beyond which the healer is able to heal. Ambassador Flamelash summons adds continually throughout the encounter, which give him a buff if they reach him. As such, these adds need to be killed away from the boss. Keep his stacks low, and this is an incredibly easy fight." },
            { en = "Panzor the Invincible",
              text = "Panzor the Invincible is a rare boss spawn within The Mold Foundry. He is fairly annoying to casters because of Spell Reflection, but outside of that, he is a fairly easy encounter. Panzor the Invincible is not a mob that will be encountered often. However, when encountered, the biggest thing is for casters to watch out for Spell Reflection. other than that, it is an easy encounter." },
            { en = "Chest of The Seven",
              text = "is another fairly easy fight. This is a multistage encounter against 7 waves of dwarven spirits. Each spirit reflects a particular class (e.g., priest, warlock, and rogue); however, it isn't worth offering unique strategy for each. They are all quite easy to kill. The only concern is killing them too slowly, which might mean you get an additional dwarf before you've completely killed the one you're focusing as they are released on a set timer. No real strategy other than killing each quickly. They will possess one or two abilities of their specific class, but in a weakened state. Try to kill them quickly to avoid fighting two or more at a time. The names of the seven dwarves are: Hate'rel Anger'rel Vile'rel Gloom'rel Seeth'rel Doom'rel Dope'rel" },
            { en = "Magmus",
              text = "Magmus is a tricky fight because of the fires coming from each side throughout the chamber. Magmus stands at the end of a long chamber. WIthin the chamber, there are two rows of fire belching golems. This fire is brutal and will kill you rapidly. As such, it is on the tank to put Magmus in a good position, so that the flames aren't an issue. Outside of the flames from the sides of the chamber, the fight is fairly easy. This fight is all about positioning the boss correctly." },
            { en = "Princess Moira Bronzebeard",
              text = "This is the final boss encounter within BRD. Groups can proceed in one of two directions. Either they can choose to save Princess Moira Bronzebeard and kill Emperor Dagran Thaurissan, or they can choose to kill both. Most groups will save Princess Moira Bronzebeard to complete the quest and then kill her each time afterwards because she had good drops." },
            { en = "Emperor Dagran Thaurissan",
              text = "This is, unquestionably, the most difficult encounter of the dungeon, so be prepared for a fun fight. However, if you're a warrior tank or dps, get super comfortable, you'll live here while working on obtaining . If you are choosing to save Princess Moira Bronzebeard, then your strategy is to keep her occupied with an off-tank, or someone who can interrupt her casts. because she can be fairly squishy. Further, she assists Emperor Dagran Thaurissan within the fight, so you can't allow her to simply free cast the entire encounter. As soon as Emperor Dagran Thaurissan dies, she breaks free from the mind control she was under to become friendly. However, if your intention is to kill Princess Moira Bronzebeard, then you burn her before killing Emperor Dagran Thaurissan. Make sure you have some form of interrupt because she can do a fair amount of damage, which can be hard to heal through coupled with the damage output of Emperor Dagran Thaurissan. Looting Princess Moira Bronzebeard can be buggy; make sure your group has completed the / chain first." },
        },
    },
    lower_blackrock_spire = {
        tagline = "LBRS: ogre halls and dragonkin lairs, ending at Overlord Wyrmthalak.",
        tips = {
            "No key needed, but start the Seal of Ascension chain for UBRS.",
            "The cave below Smolderweb's room spawns rares like Crystal Fang - /target to check.",
            "Gizrul rushes in right after Halycon dies - recover quickly between fights.",
            "Place the pike before Urok's encounter; click it every 30s to instakill an ogre.",
        },
        entrance = {
            H = "From Kargath in the Badlands, run west into Blackrock Mountain.The entrance is on the upper central platform, across from BRD.Head down the hallway into the lower section; no key required.",
            A = {
                "Fly to Morgan's Vigil in Burning Steppes (or run via Duskwood).",
                "Enter Blackrock Mountain and take the upper platform entrance.",
            },
        },
        trash = {
            { title = "Dragonspawn Guards",
              text = "Dragonspawn use frontal breath attacks - tank them facing away from the group." },
            { title = "Spirestone Orc Camps",
              text = "Orc packs contain healers and casters - interrupt and pull pack by pack." },
        },
        bosses = {
            { en = "Spirestone Butcher",
              text = "Spirestone Butcher is a level 57 elite ogre." },
            { en = "Highlord Omokk",
              text = "Highlord Omokk is a level 59 elite ogre located in Lower . Highlord Omokk is accompanied by two other Ogres. Most groups tend to CC one of the adds, while the tank picks up Highlord Omokk, keeping him away from the group, with their back against a wall due to Omokk's Knock Away. Decide within your group how to handle the adds. Either CC both if possible and kill Highlord Omokk first, or keep one add CC'd the entire time, kill the other, then Omokk. The choice is yours, but be sure crowd control is involved because it will make this encounter a lot easier. Highlord Omokk himself hits pretty hard, so healers, be sure to keep an eye on the tank's health, especially if it gets low. With his Enrage, he could dish out devastating damage, quickly." },
            { en = "Spirestone Battle Lord",
              text = "Spirestone Battle Lord is accompanied by two casters. Most groups opt to burn down the casters first and then move on to Spirestone Battle Lord, but you can also use CC here if you'd like. He's a typical melee mob, so make sure the tank has aggro before burning him down." },
            { en = "Shadow Hunter Vosh'gajin",
              text = "Shadow Hunter Vosh'gajin is a level 59 elite troll located in Lower . Shadow Hunter Vosh'gajin is accompanied by two Smolderthorn Shadow Priests. Similar to Highlord Omokk, groups typically will CC one of the mobs, and pull Shadow Hunter Vosh'gajin away from the group. This is due to her Hex, which can affect multiple group members at a time. Kill her both Smolderthorn Shadow Priests first, then focus down Shadow Hunter Vosh'gajin. If you have a or in the group, have them cleanse her Curse of Blood." },
            { en = "War Master Voone",
              text = "War Master Voone is a level 59 elite troll located in Lower . War Master Voone is not accompanied by any guards, but he hits really hard. Do not engage in the fight until you're certain tank has generated enough threat to maintain aggro. Tanks - pull him close to a wall and keep your back to the wall. If War Master Voone switches targets, stop DPS until the tank gets him back." },
            { en = "Bannok Grimaxe",
              text = "Bannok Grimaxe is a highly sought-after rare spawn in Lower , because he has a chance to drop . He spawns in the room before Mother Smolderweb, among packs of orcs, by a cluster of tents. Be sure to use /tar Bannok to see if he's spawned. If he is, he's either sitting or sleeping in a corner." },
            { en = "Mother Smolderweb",
              text = "Mother Smolderweb is a level 59 elite spider boss found within Lower . Mother Smolderweb's Crystallize is an AoE frontal cone stun. So naturally, have your tank face her away from the group. She will periodically cast Mother's Milk , a poison that stuns her target and anyone within close proximity of them. Being attentive to these 2 abilities, you can burn her down relatively easy." },
            { en = "Crystal Fang",
              text = "Crystal Fang is a rare spawn found in the area around 's lair, in Lower ." },
            { en = "Urok Doomhowl",
              text = "Urok Doomhowl is a level 60 elite summoned boss found within Lower . When Urok Doomhowl's encounter begins, many waves of elite ogres will appear first, before Urok himself. The key is to utilize the pike that you placed in the Tribute Pile. Every 30 seconds, you can click on the pike while targeting an ogre to insta-kill single ogre from a wave. This will help manage the number of mobs you fight at once per wave. Don't forget to also utilize CC in addition to clicking the pike, as these waves can get overwhelming over time. After you kill about 10 or so, Urok Doomhowl will finally appear. He's has warrior type abilities, including his Intimidating Roar fear. Make sure your tank has proper aggro before unleashing DPS on him." },
            { en = "Quartermaster Zigris",
              text = "Quartermaster Zigris is an elite boss found within Lower ." },
            { en = "Halycon",
              text = "Halycon is an elite worg boss found within Lower . Halycon comes with a group of Worg Pup. Tanks, pick up Halycon while the group kills the pup adds. Once the adds are done for, focus down Halycon. With her melee abilities, Rend and Thrash, she shouldn't be too challenging to take down. As soon as Halycon falls, replenish your health and mana ASAP, because Gizrul the Slavener will soon come running into battle!" },
            { en = "Gizrul the Slavener",
              text = "Gizrul the Slavener is an elite worg boss found within Lower . Gizrul the Slavener hits pretty hard and combined with his abilities, can dish out devastating damage with Fatal Bite, which will heal himself, and Infected Bite, a nature DoT. As usual, have your tank pick him up and generate enough threat before you unleash your DPS on him." },
            { en = "Overlord Wyrmthalak",
              text = "Overlord Wyrmthalak is the final boss of Lower . Tanks, face Overlord Wyrmthalak away from your party, with your back against a wall while generating your initial threat. He will summon adds during the fight when he reaches 50% health. Most groups will opt to CC the adds and burn Overlord Wyrmthalak down as quickly as possible, then move on to the adds once he's down." },
        },
    },
    upper_blackrock_spire = {
        tagline = "UBRS: the classic 10-15 man raid, ending with Rend Blackhand and General Drakkisath.",
        tips = {
            "UBRS requires the Seal of Ascension from an LBRS quest chain - one per group is enough.",
            "Don't crack the eggs in the Rookery - hug the walls to avoid whelp waves.",
            "Fire resistance helps a lot for Emberseer and Drakkisath, especially for tanks.",
            "Buff and consume up before the Rend gauntlet - there's no break mid-fight.",
        },
        entrance = {
            H = "From Kargath in the Badlands, run west into Blackrock Mountain.Take the upper platform entrance and fight through the LBRS hallway.A Seal of Ascension holder opens the drake door to UBRS deep in LBRS.",
            A = {
                "Fly to Morgan's Vigil in Burning Steppes (or run via Duskwood).",
                "Enter Upper Blackrock Spire through the Seal of Ascension door in LBRS.",
            },
        },
        trash = {
            { title = "Rookery Eggs",
              text = "Cracked eggs spawn whelp waves - hug the walls unless doing the Father Flame event." },
            { title = "Hall of Blackhand Garrisons",
              text = "Patrols mix with stationed mobs before Drakkisath - clear the room first." },
        },
        bosses = {
            { en = "Pyroguard Emberseer",
              text = "This room is straightforward. Click the Altar to aggro all of the Incarcerators to release the bind on Pyroguard Emberseer . Once released, kill Pyroguard to advance into The Rookery. Click the Blackrock Altar to start the fight. The Incarcerators have low health, so killing them is quite easy. Just AoE them down with mages and locks. As for Pyroguard, tanks should keep him away from the group to avoid multiple people getting hit with the fire nova. Outside of that, this fight is quite easy. Boss should die fairly quickly." },
            { en = "Solakar Flamewreath",
              text = "This room is a major wipe risk because of the eggs on the ground. Most groups avoid the Father Flame event in this room and continue around the West wall to reach the upper landing overlooking The Rookery . However, some groups opt to do the event, which is quite difficult. To start the encounter, reach Father Flame by hugging the Northern wall tightly as a raid and walking down to the far end. It is wise to clear out a few of the eggs before starting the encounter, but be aware that they will respawn fairly quickly. As such, some groups avoid focusing on this because it is seen as a futile effort. Clear out the dragonspawn before beginning the event. Then, click Father Flame and loot the item. During the event, multiple waves of mobs will come at your raid. The first is the Rookery Hatcher. They will break the eggs, so it is critical to kill these mobs immediately. Have your mages and warlocks deal with the released whelps. The second mob type of the Rookery Guardian. Have your tanks grab these mobs and tank them back against the Eastern wall. The targets have lower priority than the Hatchers. After a few minutes, Solakar will come, which is a simple encounter. Have your tank grab Solakar and position him along the wall. Finish off the remaining whelps, and then have your group focus on Solakar. Have your raid stay at range. He has a war stomp, which can stun the whole raid. Once killed, your raid should hug the wall again and work your way back around the edge of the room and up the landing. AoE whelps as they spawn, but it is possible to avoid cracking multiple eggs by hugging the corner. Rage Talon Dragonspawn Fixate Enrage Sunder Armor Rage Talon Flamescale Fireball Volley Fire Nova Flamestrike Rookery Hatcher Heroic Strike Sunder Armor Rookery Guardian Heroic Strike Sunder Armor Rookery Whelp Fireball" },
            { en = "Jed Runewatcher",
              text = "Just as with Goraluk , this fight is quite easy. Tank him back against the wall with raid group at range, which should lead to a straightforward kill. Charge Shield Bash Heroic Strike Note : Some groups will do a /tar Jed Runewatcher before beginning the run. This is where the origin of the chat message \"LFM UBRS doing Jed/Rend\" runs comes from." },
            { en = "Goraluk Anvilcrack",
              text = "This room is straightforward. The boss in this room is Goraluk Anvilcrack, but the optional boss Jed Runewatcher might also present within the Hall. Clear all the mobs then kill Goraluk Anvilcrack and Jed if present. Some groups skip this room as both are optional bosses. This fight is a basic encounter. Tank him against the wall apart from your group. Backhand Head Crack Heroic Strike" },
            { en = "Gyth",
              text = "Complete the gauntlet to beckon Rend and Gyth. The gauntlet consists of numerous waves of orcs and dragonspawn. Once completed, the Southern Gateway will open allowing passage into The Furnace. After seven to eight waves, Rend will appear riding on Gyth’s back. To combat Gyth , the MT should face Gyth away from the raid to protect them from the breath. At 20%, Rend will be knocked off Gyth’s back. The raid should kill Gyth before switching to Rend. Freeze Corrosive Acid Breath Flame Breath Your OT should immediately grab Rend as soon as he is knocked off Gyth , and position him to the side of the room. Once Gyth is slain, the raid will switch to Rend . Melee should attempt to avoid his whirlwind and cleave mechanics. He hits quite hard, so healing here is the biggest issue with killing Warchief Rend Blackhand as mana is already low going into this portion of the encounter. Whirlwind Thunderclap Cleave" },
            { en = "Warchief Rend Blackhand",
              text = "Complete the gauntlet to beckon Rend and Gyth. The gauntlet consists of numerous waves of orcs and dragonspawn. Once completed, the Southern Gateway will open allowing passage into The Furnace. After seven to eight waves, Rend will appear riding on Gyth’s back. To combat Gyth , the MT should face Gyth away from the raid to protect them from the breath. At 20%, Rend will be knocked off Gyth’s back. The raid should kill Gyth before switching to Rend. Freeze Corrosive Acid Breath Flame Breath Your OT should immediately grab Rend as soon as he is knocked off Gyth , and position him to the side of the room. Once Gyth is slain, the raid will switch to Rend . Melee should attempt to avoid his whirlwind and cleave mechanics. He hits quite hard, so healing here is the biggest issue with killing Warchief Rend Blackhand as mana is already low going into this portion of the encounter. Whirlwind Thunderclap Cleave" },
            { en = "The Beast",
              text = "The goal here within The Furnace is to kill The Beast . Berserker Charge Immolate Flamebreak Fear The Beast is a decently difficult fight because of a few mechanics. The first is a charge that can’t be avoided. As soon as the charge happens, he will return to the top aggroed target. The MT should always have the most aggro to ensure it returns properly. The second mechanic that will cause issues is the fear. Raid groups should be at max range and spread out from The Beast to avoid this mechanic. Finally, there is a fire nova ability called Flamebreak that will do fire damage and cause a knockback. Tanks should have their back to a wall to avoid being knocked back. Everyone else should attempt to back at max range to avoid taking too much AoE damage." },
            { en = "General Drakkisath",
              text = "This is the final room within Upper Blackrock Spire . General Drakkisath , the final boss, is located here. There are a few patrols within this room as well as stationed mobs. Kill General Drakkisath to complete the raid. Cleave Conflagration Flame Breath Thunderclap General Drakkisath is the most difficult by far. The most common approach is the kite method, which many groups with hunters will use. It is significantly easier than the other method. In the kiting method, the hunter will pull General Drakkisath and kite him back through into the Beast’s room. Once there, the Hunter with feign death returning Drakkisath to the raid. While this is going on, each tank will grab a Chromatic Elite Guard and burn it down. The MT will then be prepared to grab General Drakkisath . Face him away from the raid to account for the flame breath. General Drakkisath is easy on his own apart from the guards, which is why this method is favored amongst raid groups. The second strategy is similar, but without the kite. Your group can tank both the adds and General Drakkisath at the starting position. The goal is to AoE Cleave the Chromatic Elite Guards down quickly. A possible assist here is to chain fear one of the guards with a warlock, which lessens the healing burden. Either way, this method is significantly harder at lower gear levels because of the damage output between the guards and General Drakkisath . Once the guards are dead, just as with the kiting method, General Drakkisath is fairly easy on his own." },
            { en = "Darkstone Tablet",
              text = "Faction: Horde Level Required: 57 Rewards: or 8,300 experience reputation with - begins with Apothecary Zinge in , who gives you : Apothecary Zinge She asks you to find Shadowmage Vivian Lagrave, in Kargath, : Shadowmage Vivian Lagrave Shadowmage Vivian Lagrave will follow up with, , asking you to bring him . This is found inside Upper , inside The Rookery, with all of the eggs. (the Leeroy Jenkins room)" },
        },
    },
    dire_maul_east = {
        tagline = "Dire Maul East: overgrown elven ruins, from Pusillin to Alzzin the Wildshaper.",
        tips = {
            "The Crescent Key comes from a quest item dropped by Pusillin - one per group opens the doors.",
            "Warpwood elementals entangle players - free rooted teammates quickly.",
            "Pusillin runs down the path when engaged - pace the chase to avoid extra packs.",
            "At 35% Alzzin's wall crumbles and adds rush out - save AoE cooldowns.",
        },
        entrance = {
            H = "From Camp Mojache in Feralas, head north to Dire Maul.Dire Maul is a circular ruin complex; the East entrance is on the northeastern side.Without the Crescent Key, push through the main hallway; with it, open the inner doors.",
            A = {
                "From Feathermoon Stronghold in Feralas, head northeast to Dire Maul.",
                "Follow the outer wall to the eastern entrance.",
            },
        },
        trash = {
            { title = "Warpwood Treants",
              text = "They entangle players - burst down the root or free your allies quickly." },
            { title = "Satyrs & Demons",
              text = "Satyr packs in the Lower Conservatory have casters and healers - interrupt and pull carefully." },
        },
        bosses = {
            { en = "Pusillin",
              text = "Once you engage Pusillin, he will summon four (4) Wildspawn Imp to his side. Once your tank grabs aggro on Pusillin, your group can AoE down the imps. Pusillin casts a variety of Fire spells - Kick, Counterspell and other interrupts can prevent his casts from going off. Casters: watch out for his Spirit of Runn Tum, which is a self-buff increasing his size, melee haste by 20% and chance to reflect spells by 50%." },
            { en = "Zevrim Thornhoof",
              text = "Zevrim Thornhoof will periodically teleport a party member to his ritual alter and cast Sacrifice. Healers: whoever is targeted by this will need BIG heals! His other spell, Intense Pain is like an AoE Shadow Word: Pain that can be dispelled. Ranged, stand max distance to avoid this. If you have a in your group, one tactic is to enslave a Wildspawn Hellcaller or Wildspawn Shadowstalker and use them to attack Zevrim Thornhoof." },
            { en = "Hydrospawn",
              text = "Hydrospawn could be approached in 2 ways. Burn him down & ignore the Hydroling that he spawns, or AoE down the Hydroling then switch over to Hydrospawn. The Hydroling do tend to cause more damage than Hydrospawn himself, so if you choose to just burn him down quickly, keep an eye on your healers and interrupt spells when you can." },
            { en = "Lethtendris",
              text = "Lethtendris has a plethora of -related spells. Her Void Bolt is a 4-second cast and should be interrupted, as should most of the spells you see casting. She afflicts a couple of curses, so if you have a or , be sure to have them decurse the group. Her imp, Pimgib also casts a variety of fires pells. He has about 1/3 of her HP, so focus down the imp first then move on to Lethtendris." },
            { en = "Alzzin the Wildshaper",
              text = "Alzzin the Wildshaper will shape-shift into different forms. When he shape-shifts, make sure your tank reestablishes aggro before DPSing. In his initial, Satyr Form, be sure to cleanse the poison Enervate right away as it acts as a periodic mana drain. Be sure to cleanse the disease spell, Wither, as well. Both can be interrupted, so watch out for his spell casting. When he shifts into treant form, his armor increases by a lot, so using like Sunder Armor - Spell - Classic World of Warcraft and Expose Armor will help you get through this phase. He can also shape-shift into a Dire Wolf, casting abilities similar to a feral in Cat Form. At 35% health, the wall will crumble behind him and a group of non-elite adds will come running out. They're pretty easy to AoE down and finish burning down Alzzin the Wildshaper." },
        },
    },
    dire_maul_north = {
        tagline = "Storm Gordok's seat — fight your way through, or sneak out with the full tribute.",
        tips = {
            "The tribute run relies on stealth, lockpicking and traps — the more bosses you skip, the better the tribute.",
            "Bring a rogue with 300 lockpicking or an engineer — the inner door requires one of them.",
            "All three guards use melee abilities only — ranged attackers can avoid most damage by keeping their distance.",
            "Captain Kromcrush summons two adds at 50% health — save crowd control for them.",
            "On a tribute run Cho'Rush must survive — he turns friendly once King Gordok dies.",
        },
        entrance = {
            H = "Enter the Dire Maul compound, pass through the central arena interior — the Dire Maul North entrance is on the western side of the arena.",
            A = {
                "Travel to Dire Maul in central Feralas and enter the ogre compound",
                "Pass through the central arena into the interior",
                "The Dire Maul North entrance is on the western side of the arena interior",
            },
        },
        trash = {
            { title = "Patrols and pulls",
              text = "The ogres of Dire Maul North patrol in tight packs — pull back into cleared space and avoid grabbing extra groups, or pulls can fall apart quickly." },
            { title = "Knot Thimblejack",
              text = "Knot Thimblejack is imprisoned in the kitchen area — free him and trade materials dropped by the ogres for his unique recipes." },
        },
        bosses = {
            { en = "Guard Mol'dar",
              text = "Guard Mol'dar is a named ogre guarding the approach to Dire Maul North. He uses only melee-focused abilities, so the fight is not too challenging as long as your tank picks up aggro quickly and the ranged stay back to avoid Knock Away and Shield Charge. On a tribute run, do not kill him — hug the northern wall and sneak past instead." },
            { en = "Stomper Kreeg",
              text = "Stomper Kreeg is the drunken ogre chef dancing along the northern ramp — hard to miss. His Booze Spit hits the whole party, getting everyone drunk and reducing their chance to hit by 75%. Other than that it is a straightforward tank-and-spank melee fight. On a tribute run, do not kill him — wait for him to fall asleep and sneak past." },
            { en = "Guard Fengus",
              text = "Guard Fengus patrols the center of the Courtyard. Like Guard Mol'dar, he is all melee — keep the tank on him and let the ranged stay back to avoid Knock Away and Shield Charge. On a tribute run, do not kill him: stealth classes can wait for him to patrol away and loot the chest in the middle, or a class with a movement speed ability can dash in and grab it." },
            { en = "Guard Slip'kik",
              text = "Guard Slip'kik patrols the winding hallway into the Halls of Destruction. On the way, kill the Wandering Eye of Kilrogg on sight or it will summon two Netherwalker. Like the other guards, Guard Slip'kik is melee-focused — tank him up close and keep the ranged away from Knock Away and Shield Charge. On a tribute run, do not kill him — set a freeze trap on the broken trap on the ground so he gets caught when he patrols back." },
            { en = "Captain Kromcrush",
              text = "Captain Kromcrush hits very hard and can fear party members with Intimidating Shout. At around 50% health he will summon two Gordok Reaver to his side — be ready to control the adds and keep the tank's aggro on Captain Kromcrush. Casters should stay at max range, as with the other guards. On a tribute run you can skip this fight entirely by wearing the Gordok disguise and talking your way past him." },
            { en = "Cho'Rush the Observer",
              text = "Cho'Rush the Observer is King Gordok's caster attendant. In a normal run, burn him down first — he supports King Gordok, so keep his casting interrupted. On a tribute run he must survive: once King Gordok falls, Cho'Rush the Observer becomes friendly and stops attacking." },
            { en = "King Gordok",
              text = "King Gordok is the final fight of Dire Maul North and the target of the tribute run. Deal with Cho'Rush the Observer first in a normal run (see his entry), then burn the king down. On a tribute run, killing King Gordok while keeping Cho'Rush the Observer alive yields the Gordok Tribute." },
        },
    },
    dire_maul_west = {
        tagline = "Delve into the Shen'dralar ruins, break Immol'thar's chains, and face Prince Tortheldrin's madness.",
        tips = {
            "Illyanna Ravenoak fights like a hunter — standing in melee range negates most of her abilities.",
            "Clear every mana pylon before engaging Immol'thar — his shield only drops once they are destroyed.",
            "Prince Tortheldrin resets aggro after his knockback — stop DPS until the tank re-establishes threat.",
            "The corridor before Immol'thar's prison is thick with patrols — stealth classes ease the run considerably.",
        },
        entrance = {
            H = "Enter the Dire Maul compound and circle around to the western side — the Dire Maul West entrance sits among the ruined gardens on the west.",
            A = {
                "Travel to Dire Maul in central Feralas and enter the ogre compound",
                "Follow the outer path around to the western side",
                "The Dire Maul West entrance lies among the ruined gardens on the west side of the compound",
            },
        },
        trash = {
            { title = "Invisible ancients",
              text = "Invisible ancient patrols roam the Warpwood Quarter — tank classes should pull carefully, using area attacks to flush them out when needed." },
            { title = "Mana pylons",
              text = "Mana pylons line the corridor to Immol'thar's prison — destroy every one of them to drop his shield and open the way forward." },
        },
        bosses = {
            { en = "Tendris Warpwood",
              text = "Clear all of the ancients in the area before pulling Tendris Warpwood, otherwise they will all aggro together. Watch out for his AoE melee knockdown Trample — ranged should stand well back. Entangle is a root effect that can be dispelled. Wait for the tank to build threat, then burn him down." },
            { en = "Illyanna Ravenoak",
              text = "Illyanna Ravenoak fights just like a hunter, accompanied by her pet bear Ferra. All of her abilities except Immolation Trap can be negated by standing in melee range of her. Most groups burn down Illyanna Ravenoak first, then kill Ferra." },
            { en = "Magister Kalendris",
              text = "Magister Kalendris is a shadow priest-type caster. Interrupt his spells, dispel any magic off the party, and burn him down; extra shadow resistance helps a lot." },
            { en = "Tsu'zee",
              text = "Tsu'zee is a rogue-type silver elite found near the ramps in the Court of the Highborne, in Dire Maul West. Fighting Tsu'zee is like encountering a rogue, and she hits pretty hard — make sure your tank gains aggro before attacking. Dispel Blind from your party if able, then burn her down." },
            { en = "Immol'thar",
              text = "Immol'thar will summon eyes around the room — assign someone, preferably a ranged attacker, to dispose of them. He will cast Enrage at 50% health, so healers should be ready with big heals on the tank. He also randomly teleports players to the middle of the room — if it is the tank, let them run back and re-establish aggro. Clear all the mana pylons first so his shield drops." },
            { en = "Prince Tortheldrin",
              text = "Prince Tortheldrin hits hard and fast. Tank him in the corner to avoid his knockback Arcane Blast. After casting Arcane Blast his aggro resets — cease DPS until the tank gets him back, then burn him down quickly." },
            { en = "Lord Hel'nurath",
              text = "Lord Hel'nurath is a special boss in Dire Maul West that can only be summoned by warlocks carrying the three summoning items from their epic mount quest line. The ritual takes place at the altar where Immol'thar originally stood, after that boss is dead. The group must survive many waves of demons while the warlock keeps all three ritual items active; Lord Hel'nurath himself is then a straightforward kill." },
        },
    },
    stratholme_main = {
        tagline = "Return to plague-stricken Stratholme and unmask Balnazzar within the Crusade's last stronghold.",
        tips = {
            "Key-dropping mobs guard mailboxes across the instance — the third mailbox spawns Postmaster Malown.",
            "Rare spawns Skul and Hearthsinger Forresten each have two spawn points — keep an eye out as you push.",
            "Cannon Master Willey's adds can be burned down or shot with the nearby cannons.",
            "Balnazzar transforms at half health and gains a full demonic kit — crowd control any mind-controlled allies.",
        },
        entrance = {
            H = "Enter through the main gate of Stratholme in northwestern Eastern Plaguelands — the Scarlet side and Market Row both lie along this route.",
            A = {
                "Travel to the Stratholme gate in northwestern Eastern Plaguelands",
                "Enter through the main gate (the live/Scarlet side)",
                "Push up the main street through Market Row toward the Scarlet bastion",
            },
        },
        trash = {
            { title = "Mailboxes and keys",
              text = "Several locked mailboxes are scattered through the instance, each opened by a key dropped from nearby mobs; the third mailbox triggers Postmaster Malown and his three elite guards, so clear the area before opening it." },
            { title = "Manage pack size",
              text = "The live side streets are narrow and packed — use crowd control, pull one pack at a time, and watch for patrols to avoid overlapping pulls." },
        },
        bosses = {
            { en = "Skul",
              text = "Skul is a rare spawn you may encounter just before Ezra Grimm, with another spawn point on the east side of the dungeon. His mechanics are very simple — he just casts spells, which you should interrupt to reduce damage." },
            { en = "Hearthsinger Forresten",
              text = "Hearthsinger Forresten is another rare spawn, appearing north up the lane from Ezra Grimm, or east past The Unforgiven along Market Row. He casts an 8-second sleep on a random player, and his multi-shot Multi-Shot can be countered by spreading out a little." },
            { en = "The Unforgiven",
              text = "The Unforgiven spawns in the corridor labeled 4 on the map, together with a few non-elite adds, so do not engage while already fighting other mobs or at low health and mana. He has no real mechanics beyond the adds and a shadow spell that also slows." },
            { en = "Postmaster Malown",
              text = "Stratholme Courier mobs throughout the instance drop keys that open their associated mailboxes. Opening the third mailbox spawns Postmaster Malown along with three elite Undead Postman that use Wailing Dead — the stacking curse gives tanks and healers a hard time, so crowd control the adds or have a mage or the healer dispel it off the tank. Make sure the area is clear before engaging, as his fear could send you running into extra mobs." },
            { en = "Timmy the Cruel",
              text = "Timmy the Cruel is the first boss you may encounter if you head straight for the Scarlet side. He is a reference to South Park and yells \"TIMMY!\" on engage. He has no mechanics — a simple tank and spank." },
            { en = "Malor the Zealous",
              text = "Malor the Zealous has no notable mechanics apart from Lay on Hands. He is located in his own room at number 7 on the map; the chest behind him contains the item for the related quest, plus some gold and random items." },
            { en = "Crimson Hammersmith",
              text = "Summoned by clicking the blacksmithing plans on the floor at number 8 on the map. A simple tank and spank; he only drops plans for blacksmiths with the Armorsmithing specialization." },
            { en = "Cannon Master Willey",
              text = "Cannon Master Willey spawns at number 9 on the map. He summons several ranged adds during the fight — either switch to them, or grab a cannon ball near Cannon Master Willey and load it into one of the cannons to shoot them down. He has an interrupt, but apart from that the fight is simple as long as the adds are handled." },
            { en = "Archivist Galford",
              text = "Archivist Galford spawns at number 11 on the map, in a room tied to two quests — loot what you need before burning down the room. He has a DoT Burning Winds and an AoE ability, which makes the fight harder on healers; if the DoT lands on the tank, be ready for heavy damage." },
            { en = "Balnazzar",
              text = "Grand Crusader Dathrohan is the final boss of the dungeon at number 11 on the map, and turns into Balnazzar halfway through the fight. In human form he does little, but around half health he gains Domination, Psychic Scream, Mind Blast, Shadow Shock and Sleep. Crowd control the player he mind controls, stand at max range to avoid the fear if you are a caster, and dispel the sleep off your allies when you can." },
        },
    },
    stratholme_service = {
        tagline = "Push through the Service entrance to Baron Rivendare — beware the spider dens and patchwork horrors.",
        tips = {
            "The spider rooms behind three mini-bosses must be fully cleared to unlock the gates toward Ramstein and the Baron.",
            "Magistrate Barthilas knocks back — have the tank fight with his back to a wall.",
            "Pull patchwork constructs one at a time — the room gate locks once combat starts.",
            "The Baron's door closes on pull — ranged and healers standing on the bone piles ease the healing load dramatically.",
        },
        entrance = {
            H = "Enter through the same main gate, then turn right and take the service entrance (the Infectious Cavern) into the undead side.",
            A = {
                "Travel to the Stratholme gate in northwestern Eastern Plaguelands",
                "Enter through the main gate, then turn right (straight ahead is the live side)",
                "Take the service entrance (the Infectious Cavern) to reach the undead side",
            },
        },
        trash = {
            { title = "Clear the spider rooms",
              text = "The rooms behind Baroness Anastari, Nerub'enkan and Maleki the Pallid are packed with spiders — clear every one to unlock the gates toward the Baron's wing." },
            { title = "Patchwork constructs",
              text = "The patchwork constructs before Ramstein's room hit hard and summon adds — pull one at a time, and warn the group before engaging since the door locks." },
        },
        bosses = {
            { en = "Magistrate Barthilas",
              text = "Magistrate Barthilas can spawn at the church near the start, or — if alerted — run to his second spot near the end of the instance at number 12 on the map. The key ability to watch for is Mighty Blow: it knocks the tank back several yards, potentially into more mobs. Simply face your back to a wall so you get knocked straight up instead of backward." },
            { en = "Stonespine",
              text = "Stonespine is a rare spawn that appears at 14 on the map and paths up and down that section. He has no notable mechanics apart from Vicious Rend, though he does drop some decent gear." },
            { en = "Baroness Anastari",
              text = "Baroness Anastari spawns at number 15 on the map. She does not hit hard, but her kit is annoying: she casts Possess on players throughout the fight — the possessed player is freed by being brought to 50% health — silences casters, and curses players to reduce their hit chance. After she dies, clear the room behind her full of Thuzadin Acolyte, as this unlocks a gate later in the dungeon." },
            { en = "Black Guard Swordsmith",
              text = "Black Guard Swordsmith is a mini boss summoned by clicking the blacksmithing plans on the ground to the right of Baroness Anastari. He has no mechanics and no unique loot apart from a plan for blacksmiths." },
            { en = "Nerub'enkan",
              text = "Nerub'enkan spawns at number 16 on the map, northwest of the gauntlet entrance, and is usually the first boss you make your way to. As DPS, cleave down the extra mobs he spawns — they do little damage, and you may pull aggro anyway because the tank is snared or under pressure. Healers and tanks should watch for Pierce Armor and coordinate defensives and focused healing. After he dies, clear the room behind him full of Thuzadin Acolyte to unlock a gate later on." },
            { en = "Maleki the Pallid",
              text = "Maleki the Pallid is down the path north of Baroness Anastari, at 17 on the map. He will generally entomb the tank in Ice Tomb, which lasts 6 seconds — during that time healers and DPS should watch their threat. That is the only mechanic worth worrying about. After he dies, clear the room behind him full of Thuzadin Acolyte to unlock a gate later on." },
            { en = "Ramstein the Gorger",
              text = "Ramstein the Gorger spawns at number 18 on the map after you kill all the patchwork mobs in the room. The gate into the room locks once you start pulling, so let your group know, and pull the patchworks one at a time — they hit hard and can spawn extra mobs. Ramstein the Gorger himself is basically a tank and spank with aggro swaps: he casts Knockout on the tank and swaps aggro, using Trample along the way, so healers should keep some heals ready for the DPS." },
            { en = "Baron Rivendare",
              text = "Baron Rivendare is the final boss of the undead side. His kit reduces healing on the tank and deals consistent AoE damage with his aura and cleave, and he summons skeletons throughout the fight — cleave them down quickly or they will wreak havoc. A proven strategy: buff up outside and run in together, as the door closes on pull. The tank runs right and pulls him to the right side of the room with the melee; ranged DPS and the healer stand on the bone piles on the left to avoid Unholy Aura. Melee should stay behind the boss to avoid his cleave. When skeletons spawn, switching to them is the DPS priority — they die quickly and the tank does not need to pick them all up. Keep your distance from the aura and the fight becomes much easier." },
        },
    },
    excavation_wetlands = {
        tagline = "A mist-shrouded dig site above Whelgar's Excavation in the Wetlands, where errant Titan constructs stir: 4 bosses.",
        tips = {
            "The dungeon is listed at levels 24-29 (Group Finder says 26-33) and is now open in the beta — boss strategies below will be re-checked as the beta moves on.",
            "The files name four areas inside: Lost Marsh, Stalker's Thicket, Site of the Guardian and Lost Dig Site.",
            "Around the portal live level 26 Highland Tortoises and elite Highland Lurkers of 28-29 — don't pull them while finding the entrance.",
            "The Legacy challenge counts the dungeon as done only when the last boss, the Relic Guardian, dies.",
            "The entrance is a column of blue mist under a large tree, reached from Thelgen Rock.",
        },
        entrance = {
            H = "",
